insert into public.guide_revision_archive(guide_id,revision,content) values
('identify-your-engine','bffabae78e2e7427069e0d7e','{"slug":"identify-your-engine","title":"Identify the engine before choosing a procedure","system":"engine","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","duration":"5 min read","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"reference","summary":"Match a car to the manual''s engine families and record what is still unknown before opening a repair or ordering a part.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"Foreword p. v; 100-1","pdfPages":[5,43]},"tools":["Vehicle records","Camera or notebook"],"cautions":["A model badge or model year alone does not prove which engine is currently installed.","This source establishes U.S. applications only; a swap needs its own identification evidence."],"steps":[{"title":"Record the actual vehicle","body":"Save the model, market, model year and available production date. Keep an unknown value explicitly unknown.","check":"The vehicle record distinguishes an observed fact from an assumption."},{"title":"Choose a source-supported starting point","body":"The manual groups U.S. 1989-1990 525i with M20, 1991-1992 525i with M50, and 1993-1995 525i with M50TU. Its 535i uses M30, and its 1994-1995 530i/540i use M60.","check":"A starting engine family is selected, or no supported match is claimed."},{"title":"Check the car against its history","body":"Compare the starting point with existing engine identification records and any documented modifications. Resolve a mismatch before using engine-specific instructions.","check":"The guide filter reflects the installed engine or remains unconfirmed."},{"title":"Carry the identity forward","body":"Attach the vehicle and engine family to your repair question and parts inquiry. Verify production restrictions separately before purchasing.","check":"Other members can see the configuration and unresolved details."}]}'::jsonb),
('cooling-system-visual-check','355ab87150fd6bf2a1f95a8b','{"slug":"cooling-system-visual-check","title":"Start an overheating investigation with a cold inspection","system":"cooling","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","duration":"15-25 min","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"inspection","summary":"Create a useful first record of coolant loss, belt condition, hoses and radiator airflow before treating a suspected component as a confirmed failure.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"170-1 to 170-2","pdfPages":[205,206]},"tools":["Inspection light","Eye protection","Gloves","Notebook or camera"],"cautions":["Wait until the engine and cooling system are fully cold. Never open a hot or pressurized coolant cap.","Keep coolant away from people and animals and contain any spill.","Keep hands clear of fans and belts; the electric fan can operate when the ignition is on."],"steps":[{"title":"Make the work area safe","body":"Park securely, switch the engine and ignition off, and let the system cool completely. This is a visual inspection; do not start a hot-system test.","check":"The engine is off, the key is removed, and the system is cold."},{"title":"Record level and visible leakage","body":"Observe the available cold-level markings and look for wet areas or dried residue around the engine, expansion tank, radiator and hose connections. Do not assume the first wet area is the source.","check":"Each observation has a location and a photo or written description."},{"title":"Look over hoses and the drive belt","body":"Check accessible hoses for cracking or obvious deterioration, inspect clamp areas for leakage, and look at the coolant-pump drive belt for visible damage.","check":"Any damaged or uncertain item is recorded for a closer engine-specific inspection."},{"title":"Inspect the radiator air path","body":"Look for dirt, leaves or debris obstructing the radiator and record any obvious damage. Keep tools and fingers outside the fan area.","check":"The record distinguishes an airflow obstruction from a coolant-flow suspicion."},{"title":"Choose the next test from the evidence","body":"A visual check cannot rule out an internal leak, circulation fault or fan-control fault. Take the recorded observations to the appropriate test or a qualified workshop.","check":"The next action is a test supported by an observation, rather than an unverified parts replacement."}]}'::jsonb),
('cooling-fan-airflow-check','ec0626f718e48c7bed2d7c3e','{"slug":"cooling-fan-airflow-check","title":"Separate an airflow concern from a fan diagnosis","system":"cooling","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","duration":"10-15 min","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"inspection","summary":"Understand the mechanical fan and auxiliary electric fan, then gather cold, engine-off observations useful for an overheating-at-idle question.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"170-1; 170-3","pdfPages":[205,207]},"tools":["Inspection light","Notebook or camera"],"cautions":["Perform this visual inspection with a cold engine, ignition off and air conditioning off.","Never try to stop a moving fan or reach into its blades.","No powered fan test, connector bridging or hot-engine test is included here."],"steps":[{"title":"Describe when the symptom happens","body":"Record whether the reported overheating happens at idle, in traffic, at speed or under load. The manual identifies primary-fan faults as one possible cause of overheating during prolonged idling.","check":"The report includes conditions and observations without asserting a failed part."},{"title":"Identify the two fan arrangements","body":"From a safe view with the engine off, locate the pump-driven primary fan and the electric auxiliary fan ahead of the radiator. The fan clutch regulates the primary fan coupling.","check":"The question names the fan being discussed instead of using an ambiguous \"fan\" label."},{"title":"Inspect visible condition","body":"Look for damaged blades, obstructions and visible fluid leakage near the viscous clutch. Record what is visible without reaching into the fan assembly.","check":"Photos or notes identify the observed issue and its location."},{"title":"Escalate to the appropriate controlled test","body":"A still fan alone is not proof of a fault. Use the engine-specific fan-check procedure and wiring evidence for the next test, or ask a workshop to perform it.","check":"The next test is chosen; the observation has not been marked as a verified diagnosis."}]}'::jsonb),
('m50-water-pump-job-planning','5c458d5b100cc7b4c5c2b469','{"slug":"m50-water-pump-job-planning","title":"Plan an M50 coolant-pump job","system":"cooling","engines":["M50","M50TU"],"level":"Intermediate","duration":"10 min planning","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"planning","summary":"Check the parts and bleed procedure first, then follow the source-checked mechanical sequence for fan access, pump extraction, seal installation and even tightening.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. 1991–95 E34 525i with an installed M50 or M50TU, the four-stud pump and the matching belt and cooling hardware. Check any replacement or modified hardware against its own instructions.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"170-8–170-9, Figs. 12–13; 170-12; 020-13","pdfPages":[35,212,213,216]},"tools":["Applicable cooling fill and bleed procedure","Fan wrench and pulley holder","Two matching M6 extraction bolts","New pump and seal, low-range torque wrench and coolant containment"],"cautions":["Do not open or drain a hot cooling system.","The fan-clutch attachment uses a left-hand thread; consult the proper removal procedure before applying force.","Installation loads, tightening specifications, coolant choice and bleeding must be verified for the actual vehicle and replacement parts."],"steps":[{"title":"Confirm the M50 application","body":"Check the installed engine identity and review the M50-specific pump procedure rather than borrowing the M20, M30 or M60 steps.","check":"The engine and any modification are recorded."},{"title":"Plan access before draining","body":"Confirm the fill and bleed procedure for the installed reservoir before opening the system. On a cold engine, isolate the battery and drain into a suitable container. Remove the fan and shroud with the source-specific holding method. Move the documented thermostat housing hoses, loosen the pump pulley hardware, and remove the belt and pulley using the matched tensioner procedure.","check":"The work can proceed safely without improvising a missing holding or access tool."},{"title":"Extract the old pump squarely","body":"Match the replacement and seal to the actual housing. Remove the four pump retaining nuts. Thread two matching M6 bolts into the opposed extraction ears shown in Fig. 13 and advance them evenly until the pump releases. Stop for damaged threads or an uneven release. Keep tools clear of the mating bore.","check":"The pump comes out squarely and the studs and sealing bore are undamaged."},{"title":"Fit the new seal and tighten evenly","body":"Clean the mating bore, fit a new seal and use only a seal-compatible assembly lubricant specified for the installed pump. Locate the pump squarely over the studs and tighten the four nuts alternately and evenly. Bentley lists 10 Nm for the factory pump-to-cover nuts and 10 Nm for the pump pulley fasteners. Confirm these values for the actual hardware.","check":"The seal is seated without pinching, the pump is flush and the applied torques are recorded."},{"title":"Restore the cooling system and verify","body":"Restore the pulley, belt, hoses, fan and shroud, then check routing and clearance. Follow the verified fill and bleed procedure for the installed cooling system before running the engine. Include a leak check, controlled temperature check and a final cold-level recheck. Stop for an unknown cap or bleed sequence, leakage or abnormal temperature.","check":"The job checklist includes completion verification rather than ending when the new part is installed."}]}'::jsonb),
('battery-connections-first-check','3b60d5c1f6145f24b09ade71','{"slug":"battery-connections-first-check","title":"Inspect battery cables and grounds before blaming the alternator","system":"electrical","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","duration":"15 min","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"inspection","summary":"Gather the basic connection, ground and belt observations that help a charging or slow-cranking investigation.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"121-1","pdfPages":[163]},"tools":["Inspection light","Eye protection","Gloves","Notebook or camera"],"cautions":["Battery acid and explosive charging gas require eye and skin protection and no sparks, smoking or flame.","Do not bridge battery terminals with tools or jewelry.","This page does not instruct battery disconnection, charging or live electrical testing."],"steps":[{"title":"Find the battery for this configuration","body":"The source locates it in the engine compartment on U.S. 1989-1991 525i and under the rear seat on 1992-on 525i and the covered 530i, 535i and 540i. Confirm the actual installation.","check":"The location is observed on the car and any modification is recorded."},{"title":"Inspect without disturbing the connections","body":"With the ignition off, look for visible corrosion, cable damage and an obviously loose connection. Avoid touching both terminals or placing a tool between a terminal and bodywork.","check":"Visible connection issues are documented, not hidden by an immediate parts swap."},{"title":"Follow the ground path visually","body":"Inspect accessible battery-to-body and engine-to-body ground connections for damage or corrosion. Do not infer electrical continuity from appearance alone.","check":"The report identifies which ground connection was observed."},{"title":"Check the alternator belt visually","body":"With the engine stopped, inspect the accessible belt for obvious wear or damage. Belt adjustment and replacement require the applicable engine procedure.","check":"Belt condition is recorded separately from battery or alternator condition."},{"title":"Request the next measurement","body":"If the cause remains unclear, use a suitable charging-system diagnostic procedure or workshop test. A visual inspection alone cannot certify battery capacity or alternator output.","check":"The next step is a defined measurement with the vehicle identity attached."}]}'::jsonb),
('front-strut-component-identification','d42647ea4f23a5c5480bb16f','{"slug":"front-strut-component-identification","title":"Identify a front strut assembly and its production differences","system":"suspension","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","duration":"8 min read","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"reference","summary":"Learn the front-suspension component names and why the upper strut stack must be checked against the car''s configuration.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"310-1 to 310-4","pdfPages":[277,278,279,280]},"tools":["Vehicle production information","Parts diagram or camera"],"cautions":["Do not loosen the strut shaft nut or disassemble a spring-loaded assembly for identification.","Spring work requires suitable equipment and the complete procedure.","Do not treat a visual teaching diagram as a fitment guarantee."],"steps":[{"title":"Distinguish the nearby components","body":"The front suspension includes the strut, control arm, thrust arm, stabilizer link, crossmember and center tie rod. Use these names to locate the subject of a noise or parts question.","check":"The report identifies a component or clearly states that its location is uncertain."},{"title":"Read the strut as an assembly","body":"The strut stack includes the mount, spring seats and pads, spring, cartridge and housing; the bump stop and protective tube are additional service items.","check":"The requested item is not confused with the entire strut assembly."},{"title":"Check the production split","body":"The manual shows different upper stacks for 1989-1992 and 1993-on applications. It also notes that some mounts correct camber and carry a plus or minus marking.","check":"Production information and any observed mount marking are included with the inquiry."},{"title":"Verify fitment before ordering","body":"Check the car''s actual strut and mount configuration, including prior modifications, against documented parts applicability. The source diagram does not establish an OEM number for every item.","check":"The part remains unconfirmed until the vehicle and catalog evidence agree."}]}'::jsonb),
('engine-air-filter-replacement','bbb9302557d978655c0dcffb','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"engine-air-filter-replacement","jobSupport":{"reviewedOn":"2026-11-10","sourceSha256":"23032c541d08d764921449cb13751e77847abaeb720abb21e30401e22797322a","requiredParts":["Air filter element matched to the installed housing"],"conditionalParts":["Cracked lid, missing clip or damaged intake connection after inspection"],"stopConditions":["Broken housing or clip prevents the lid from seating","Replacement seal does not match the housing","Debris has entered the clean-side intake","Lid cannot move without pulling on a hose or wire"],"steps":[{"number":1,"tools":["Light"],"source":{"printed":"020-10","pdf":32,"href":"/manual/020?pdf=32"}},{"number":2,"tools":["Socket or nut driver, where fitted"],"source":{"printed":"020-10","pdf":32,"href":"/manual/020?pdf=32"}},{"number":3,"tools":["Lint-free cloths"],"source":{"printed":"020-10","pdf":32,"href":"/manual/020?pdf=32"}},{"number":4,"tools":["Light","Socket or nut driver, where fitted"],"source":{"printed":"020-10","pdf":32,"href":"/manual/020?pdf=32"}}]},"title":"Replace the engine air filter","system":"engine","kind":"replacement","duration":"15–25 min","summary":"Open the factory clip-fastened airbox, replace the element and check the perimeter seal before starting the engine.","applicability":"Bentley-covered U.S. 525i, 535i, 530i and 540i with the original two-piece, spring-clipped intake housing. Confirm the installed housing and element on cars with intake changes.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-10, Figs. 5–6","pdfPages":[32]},"tools":["Light","Lint-free cloths","Socket or nut driver, where fitted"],"cautions":["Switch the ignition off and let the engine cool. Keep grit and tools clear of the clean-side intake opening.","Support the airbox lid and attached intake duct. Stop if age-hardened plastic or wiring prevents access without force."],"steps":[{"title":"Locate the airbox and check the replacement","body":"Follow the intake duct to its rectangular filter housing. Bentley locates the M20/M50 housing at the left front and the M30/M60 housing at the right front, using vehicle left and right. Confirm the element against the installed housing.","check":"The replacement matches the filter outline, depth and sealing lip."},{"title":"Release the perimeter clips","body":"Note how the upper lid locates in the lower housing. Release the spring clips around the joint and lift the lid only far enough to withdraw the filter. Keep the lid supported so it does not pull on the duct or airflow-meter wiring.","check":"The filter lifts out without straining a hose, wire or clip."},{"title":"Clean the housing and seat the element","body":"Note which side of the old filter faced incoming air. Wipe dirt from the housing with a lint-free cloth, keeping debris out of the outlet to the engine. Seat the replacement in the same orientation and follow any locating features on its frame.","check":"The filter lies flat and the seal follows the housing edge with no fold or gap."},{"title":"Close and inspect the intake","body":"Engage the lid locators, lower the lid evenly and refasten each clip and any retaining nut fitted to that housing. Check the attached intake duct and connector for anything disturbed during access. Remove the cloth and tools before starting.","check":"The airbox joint is closed all around and every fastener and disturbed connection is secure."}]}'::jsonb),
('windshield-wiper-blade-replacement','0cc2dc31c5521182bcd39451','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"windshield-wiper-blade-replacement","title":"Replace the front windshield wiper blades","system":"electrical","kind":"replacement","duration":"15–20 min","summary":"Release the original front blade retainers, seat each replacement and check sweep and park on wet glass.","applicability":"Front windshield blade assemblies on Bentley-covered U.S. E34s with the retainer shown in group 611. Check both blade lengths and adapters. Touring rear blades, rubber inserts and wiper-arm adjustment are separate jobs.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-18 and 611-1 to 611-2, Fig. 1","pdfPages":[40,387,388]},"tools":["Correct left and right blade assemblies","Folded towel","Water or washer fluid"],"cautions":["Park the wipers and turn the ignition off before lifting an arm. Hold the spring-loaded arm whenever the blade is off.","Lay a folded towel on the glass under the arm. Stop if the arm will not lift freely or the new adapter does not latch."],"steps":[{"title":"Match the attachment on each arm","body":"Compare blade lengths and the attachment to the installed hardware. Work on one side at a time and identify the spring tab or pair of tabs before releasing the blade.","check":"The correct replacement is ready for this arm and its latch matches."},{"title":"Release the blade without dropping the arm","body":"Lift the arm off the protected windshield. Turn the blade roughly across the arm to reach the latch. Hold the arm steady, press the retaining tab or tabs and slide the blade out of the attachment.","check":"The old blade is free and the bare arm is still supported above the glass."},{"title":"Fit and test the new blade lock","body":"Slide the new assembly into the mount until its retainer engages. Gently pull against the latch by hand before lowering the arm onto the glass. Repeat for the other side.","check":"Neither blade slides out, and both sit normally against the windshield."},{"title":"Verify sweep and park","body":"Remove the towel, wet the glass and test the wipers from the driver’s seat with hands clear. Check both blades for clearance through the sweep and see whether they return to their parked position. Stop if a blade moves on the arm, strikes trim or leaves visibility impaired.","check":"Both blades stay attached, wipe cleanly and return to park without interference."}]}'::jsonb),
('accessory-drive-belt-inspection','230f468829a63d158784fce3','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"accessory-drive-belt-inspection","jobSupport":{"reviewedOn":"2026-11-10","sourceSha256":"23032c541d08d764921449cb13751e77847abaeb720abb21e30401e22797322a","requiredParts":["No replacement part is needed for inspection"],"conditionalParts":["Replacement belt only after matching the installed routing and accessory drive","Tensioner, pulley or leaking component only after diagnosis"],"stopConditions":["Engine or fan could start during the inspection","Belt is torn, displaced, frayed or contaminated","Access needs a guard removed, tensioner released or the engine turned without the matching procedure"],"steps":[{"number":1,"tools":["Flashlight","Camera"],"source":{"printed":"020-12 to 020-13","pdf":34,"href":"/manual/020?pdf=34"}},{"number":2,"tools":["Flashlight","Inspection mirror","Camera"],"source":{"printed":"020-13","pdf":35,"href":"/manual/020?pdf=35"}},{"number":3,"tools":["Compatible rib-wear gauge, for an accessible poly-ribbed belt"],"source":{"printed":"020-13","pdf":35,"href":"/manual/020?pdf=35"}},{"number":4,"tools":["Flashlight","Inspection mirror"],"source":{"printed":"020-13","pdf":35,"href":"/manual/020?pdf=35"}},{"number":5,"tools":["Camera"],"source":{"printed":"020-13","pdf":35,"href":"/manual/020?pdf=35"}}],"additionalSources":[{"title":"Gates TT002-15: inspecting EPDM belt wear","url":"https://www.gates.com/content/dam/documents-library/tech-tips-bulletins/tt002-15.pdf"}]},"title":"Inspect accessory drive belts for wear","system":"engine","kind":"inspection","duration":"10–20 min","summary":"Identify the visible belt arrangement and check for glazing, cracking, separation, contamination or poor tracking with the engine off.","applicability":"Factory accessory drives on the covered U.S. E34 engines. Bentley groups M20/M30 V-belts separately from M50/M60 poly-ribbed belts. Verify the actual tensioner and routing before any replacement.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-12 to 020-13, Figs. 9–11","pdfPages":[34,35]},"tools":["Flashlight","Inspection mirror","Camera","Compatible rib-wear gauge, for an accessible poly-ribbed belt"],"cautions":["Engine off, key out and engine cool. Keep hands and tools clear of fans, belts and pinch points.","This check is visual. Releasing a tensioner or turning the engine to expose the rest of a belt requires its own procedure."],"steps":[{"title":"Separate the accessory belts from the timing drive","body":"Identify the visible belts driving accessories at the front of the engine. Note the narrow V-profile or multiple small ribs, and count the visible belts. The M20 camshaft belt under its cover is outside this inspection.","check":"You have recorded the belt type and the visible route for each accessory belt."},{"title":"Inspect each accessible span","body":"Use a light and mirror to inspect the visible faces and edges. Look for polished contact surfaces, cracks, loose strands, separated layers, missing ribs or wet oil. Record which surfaces you could see and which remained hidden.","check":"Photos identify the affected belt, location and type of damage."},{"title":"Check rib wear on a modern replacement belt","body":"EPDM poly-ribbed belts can lose material without obvious cracking. Where the ribs are safely accessible with the engine off, use a compatible belt-wear gauge exactly as its maker instructs. Do not release the tensioner, turn the engine or force access as part of this check. If the belt cannot be measured safely, record that limitation and arrange the proper access procedure.","check":"The record includes the gauge result or clearly says which belt area could not be checked."},{"title":"Check belt seating and nearby traces","body":"Look for a belt riding at an angle, on a pulley edge or outside its expected grooves. If there is fluid on the belt, look for traces above or beside it from a safe position. Note a reported squeal separately from the visible condition.","check":"The record separates belt condition, seating and any possible leak."},{"title":"Decide what needs further work","body":"A torn, displaced or contaminated belt needs assessment before the engine is run again. Establish the correct routing, belt and tensioning hardware before replacement, and address the source of contamination. Do not use belt dressing to mask a squeal.","check":"The next action accounts for the specific belt and observed fault."}]}'::jsonb),
('brake-fluid-level-inspection','661e62165dc6018de55b9660','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"brake-fluid-level-inspection","title":"Check the brake and clutch fluid reservoir","system":"brakes","kind":"inspection","duration":"5–10 min","summary":"Read the brake reservoir level through the wall and document a low or falling level for hydraulic diagnosis.","applicability":"Bentley-covered U.S. E34s with the original marked brake-fluid reservoir. On manual-transmission cars the brake reservoir also feeds the hydraulic clutch. This is an external level check.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-15, Fig. 16; 020-16","pdfPages":[37,38]},"tools":["Flashlight","Camera or service log"],"cautions":["Keep the reservoir closed. Fluid is poisonous and can damage painted surfaces.","If the level is below MIN, there is an active leak, or the pedal is soft or sinking, do not drive. Arrange inspection and recovery."],"steps":[{"title":"Identify the correct reservoir","body":"Park on level ground with the engine off. Find the reservoir at the brake master cylinder. Verify its markings and distinguish it from the coolant and steering reservoirs.","check":"The MIN and MAX marks you are reading are on the brake-fluid reservoir."},{"title":"Read the level against both marks","body":"Look squarely at the marked wall using a light. Record the level in relation to MIN and MAX and whether the marks and fluid line were visible. If you cannot read it reliably, leave the observation unresolved.","check":"The record includes a visible level and date, or states that the reading was inconclusive."},{"title":"Capture any symptoms and change over time","body":"Note any warning lamp, change in pedal behavior or visible wetness near the reservoir or hydraulic connections. A gradual change can accompany pad wear, while a low or falling level also warrants a leak check. On a manual car include any change in clutch behavior.","check":"The next inspection can distinguish brake wear, brake hydraulic leakage and possible clutch hydraulic leakage."},{"title":"Route a low reading to diagnosis","body":"Keep a dated photo and describe the level and symptoms together. Use the brake and clutch source sections as applicable to have the loss investigated before returning the car to service.","check":"A low reading remains open until its cause is resolved."}]}'::jsonb),
('power-steering-fluid-level-inspection','5a990239c85ab6caf4f9165e','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"power-steering-fluid-level-inspection","title":"Identify and check the power-steering fluid","system":"suspension","kind":"inspection","duration":"10–15 min","summary":"Read the reservoir marking and dipstick on the applicable steering system, then record the level and any evidence of leakage.","applicability":"Bentley-covered U.S. E34s with a labeled reservoir and MIN/MAX dipstick as shown in Fig. 15. Verify the installed hydraulic configuration and any shared systems before using a service procedure.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-15, Fig. 15","pdfPages":[37]},"tools":["Clean lint-free cloth","Flashlight","Camera"],"cautions":["Use level ground, engine off. Clean around the cap before opening and keep dirt out of the reservoir.","ATF and CHF systems require different fluids. Verify the installed system and applicable specification before adding anything."],"steps":[{"title":"Confirm the reservoir identity","body":"Find the steering-fluid reservoir and read its marking before opening it. Record the label exactly and note whether the car has shared hydraulic equipment or replacement parts. A faded or missing label leaves fluid identity unresolved.","check":"The reservoir is identified and its label or lack of one is documented."},{"title":"Read the dipstick marks","body":"On the source-shown unit, remove the cap and inspect the integral dipstick. Use the matching vehicle procedure for the dipstick seating and read the fluid line against the MIN and MAX marks. Refit the cap securely by hand.","check":"The reading is recorded with its conditions, and the cap is back in place."},{"title":"Look for a source of loss","body":"From above, inspect the reservoir and accessible hose connections for fresh wetness. Note any recent fluid additions, steering noise or change in assistance. A level check alone cannot identify a bad pump or steering box.","check":"Low or falling level, leaks or loss of assistance have a separate diagnosis before further use."}]}'::jsonb),
('cold-tire-pressure-check','5aa249bd5ab14aabffe6f3b5','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"cold-tire-pressure-check","title":"Check and set cold tire pressures","system":"suspension","kind":"inspection","duration":"10–15 min","summary":"Match the door-pillar placard to your tires and load, measure each wheel cold and track repeat losses.","applicability":"Factory tire sizes and load combinations listed for the actual vehicle. For a non-listed tire size, confirm the correct cold settings for the installed combination before adjusting.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-16, tire inflation","pdfPages":[38]},"tools":["Tire pressure gauge","Air supply","Driver-door pillar placard or matching owner’s manual"],"cautions":["Check when the tires are cold. Use the vehicle’s cold pressure for the applicable axle and load, within the tire’s limits.","Do not bleed a hot tire down to the cold target. A visibly damaged tire or one that will not hold pressure needs inspection before driving."],"steps":[{"title":"Read the correct placard row","body":"Compare the front and rear tire sizes with the driver-door pillar placard or matching owner’s manual. Choose the load condition that applies and record both axle targets in the units shown.","check":"You have a verified front and rear cold target for the actual tire sizes and load."},{"title":"Measure before adding air","body":"Wait at least three hours after driving for a cold reading. Remove each valve cap and seat the gauge squarely until the reading stabilizes. Record the four readings by wheel position and note any one tire substantially lower than the rest.","check":"All four readings and their units are recorded before adjustment."},{"title":"Set each tire and recheck it","body":"Adjust in short increments to the appropriate axle target, rechecking with the same gauge. Refit the valve caps. If the car has a serviceable spare, check it separately against its own specified pressure.","check":"Each wheel is at its verified target and each valve has its cap."},{"title":"Follow up on repeat loss","body":"Save the date, ambient conditions and readings. If one tire repeatedly loses more pressure than the others, have the tire, valve and wheel inspected for leakage. A pressure adjustment does not repair a puncture or damaged sidewall.","check":"The next cold measurement can be compared wheel by wheel."}]}'::jsonb),
('m50-engine-oil-and-filter','82ff9afad8ff10385bc7b214','{"engines":["M50","M50TU"],"level":"Intermediate","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"m50-engine-oil-and-filter","jobSupport":{"reviewedOn":"2026-11-10","sourceSha256":"23032c541d08d764921449cb13751e77847abaeb720abb21e30401e22797322a","requiredParts":["Matched cartridge with all applicable cover/center-bolt O-rings","New metal drain-plug sealing washer","Engine oil appropriate to the installed engine, current product guidance and operating conditions"],"conditionalParts":["Damaged plug or filter-cover hardware only after matching the actual housing/thread","Replacement seals omitted from a chosen filter kit must be sourced separately"],"stopConditions":["Unsafe lifting/support or access","Oil too hot to handle safely","Damaged threads or sealing face","Unknown plug/cover specification","Pressure warning remains on after start","New active leak"],"steps":[{"number":1,"tools":["Light"],"source":{"printed":"020-9","pdf":31,"href":"/manual/020?pdf=31"}},{"number":2,"tools":["Socket set and ratchet","Drain pan","Torque wrench","Gloves and eye protection","Lifting and support equipment, if needed"],"source":{"printed":"020-9","pdf":31,"href":"/manual/020?pdf=31"}},{"number":3,"tools":["Socket set and ratchet","Torque wrench","Lint-free cloths"],"source":{"printed":"020-9","pdf":31,"href":"/manual/020?pdf=31"}},{"number":4,"tools":["Funnel"],"source":{"printed":"020-8","pdf":30,"href":"/manual/020?pdf=30"}},{"number":5,"tools":["Light","Lint-free cloths"],"source":{"printed":"020-10","pdf":32,"href":"/manual/020?pdf=32"}}]},"title":"Change the oil and cartridge filter on an M50 525i","system":"engine","kind":"replacement","duration":"45–75 min","summary":"Drain the engine oil, renew the cartridge and seals, then verify oil pressure, level and leaks before driving.","applicability":"U.S. E34 525i with an installed M50 or M50TU and factory-type sump and cartridge housing. Confirm the actual drain plug and filter lid hardware. The M20 spin-on filter and aftermarket sump or housing hardware use different instructions.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-8 to 020-10, Table e and Figs. 3–4","pdfPages":[30,31,32]},"tools":["Light","Socket set and ratchet","Torque wrench","Drain pan","Funnel","Lint-free cloths","Gloves and eye protection","Lifting and support equipment, if needed"],"cautions":["Use firm, level ground and immobilize the car. Never get under a car supported only by a jack. If you need to lift it, use the approved lifting and support points and the procedure in Bentley 010.","Warm oil drains quickly and can burn. Keep hands clear of the stream. Let the oil cool enough to handle safely.","If the pressure warning stays on after starting, shut the engine off immediately and resolve the cause before restarting."],"steps":[{"title":"Confirm the filter, seals and tightening values","body":"Identify the sump drain plug and the actual cartridge cover fastener before opening either. Bentley 020-9 lists 25 Nm for an original M12 sump plug and 60 Nm for M22. It lists 33 Nm for an M10/M12 filter-cover bolt and 25 Nm for a screw-on cover. These are different fasteners. Confirm the installed hardware and use its applicable instructions if it differs.","check":"The drain plug and cover each have their own confirmed value, and the filter, new washer and all applicable O-rings are on hand."},{"title":"Drain the sump and refit the plug","body":"Warm the engine briefly, switch it off and position the pan to catch the full stream. Identify the engine sump independently of the transmission. Release the plug, drain the oil and clean the mating face. Install the plug by hand with its new washer, then tighten to the confirmed value.","check":"The plug started cleanly by hand and the new washer is seated. A damaged thread or sealing face stops the job."},{"title":"Replace the cartridge and seals","body":"Remove the filter cover and lift out the old cartridge. Note the exact grooves for the cover and center-bolt seals, where fitted. Replace each old seal, lubricate the new seals with clean engine oil and seat the new element. Refit and tighten the cover using the confirmed value for that housing.","check":"No old seal remains in a groove. Each new seal sits flat and the lid is fully seated."},{"title":"Refill by the dipstick","body":"With the car level, add suitable oil in stages. Bentley lists about 5.75 L for the M50 with a filter change. Residual oil and hardware changes affect the amount needed. Check the dipstick after the oil settles and leave the reading within the marked range before starting.","check":"Filler cap and dipstick are in place and the level is in range."},{"title":"Check pressure, leaks and final level","body":"Start from the driver’s seat and watch the oil pressure warning. Stop immediately if it stays on. Once normal pressure is indicated, check for fresh leaks from a safe position. Switch off, allow the oil to settle, recheck on level ground and correct the level in small amounts. Recycle the used oil and filter at an appropriate collection point.","check":"Warning clears, drain and housing are dry, and the final dipstick reading is in range."}]}'::jsonb),
('factory-halogen-headlight-bulb','f965f2e354ac0411f4f45edf','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"factory-halogen-headlight-bulb","title":"Replace a factory twist-lock halogen headlight bulb","system":"electrical","kind":"replacement","duration":"15–30 min","summary":"Identify the failed beam, access the rear of the lamp and verify the replacement is fully seated before testing.","applicability":"Source-matching factory U.S. halogen housings with the rear quarter-turn bulb mount shown in Bentley 630. Check the actual lamp and bulb specification. Other retention systems and HID or LED conversions need their own procedure.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"630-1 to 630-2, Figs. 1–2; 121-1","pdfPages":[163,407,408]},"tools":["Correct halogen bulb for the installed housing","Screwdriver for the rear cover","Clean gloves and a light","Tool for the negative battery terminal"],"cautions":["Turn off the lamps and ignition and let the bulb cool. Follow Bentley 121 for safe negative-battery cable isolation and any radio-code preparation.","Handle halogen bulbs by their base. Do not use this method on high-voltage retrofit lighting or force a mismatched socket."],"steps":[{"title":"Identify the lamp and verify the bulb","body":"Identify which side and beam failed before isolating the battery. Confirm the replacement specification and connector against the housing and vehicle information.","check":"You have the correct replacement for that position and the electrical supply is isolated."},{"title":"Open rear access","body":"Under the bonnet, remove the protective cover behind the headlight. On the driver’s side, move the alternator cooling duct first if it blocks the cover. Keep the cover screws and duct hardware together.","check":"The rear bulb base is accessible without disturbing the headlamp adjusters."},{"title":"Release the old bulb and seat the new one","body":"Looking at the lamp from behind, turn the original bulb base counterclockwise a quarter turn. Withdraw it and release the connector at its latch. Compare the old and new tabs. Reconnect the replacement, align the tabs with the housing slots and lock it with a clockwise quarter turn.","check":"The base sits flush, turns to its stop and has no play. The connector is latched."},{"title":"Restore the covers and verify the beam","body":"Refit the protective cover and any duct removed. Restore the battery connection per the applicable procedure. Test low and high beams, watch for a bulb warning and compare the projected pattern with the opposite side. An abnormal pattern or recurring warning needs inspection before driving in low visibility.","check":"Both beams operate as expected, covers are secure and the repaired bulb does not sit crooked."}]}'::jsonb),
('sedan-tail-lamp-bulb','edadc792261b6603630149f0','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"sedan-tail-lamp-bulb","title":"Replace a body-mounted tail lamp bulb on an E34 Sedan","system":"electrical","kind":"replacement","duration":"10–20 min","summary":"Access the original twist-lock holder behind the trunk liner and verify the replacement lamp function.","applicability":"Bentley-covered U.S. E34 Sedan with the body-mounted rear lamp and removable quarter-turn socket shown in group 630. Excludes Touring, trunk-lid and center high-mounted lamp assemblies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"630-1, electrical precautions; 630-4, Fig. 10; 121-1","pdfPages":[163,407,410]},"tools":["Replacement bulb matched to the position and rating","Light","Tool for the negative battery terminal"],"cautions":["Switch off the lamps and ignition, allow the bulb to cool and isolate the negative battery terminal per the vehicle procedure.","Stop for melted contacts, water intrusion or brittle wiring. A new bulb will not repair a damaged socket."],"steps":[{"title":"Identify the failed function","body":"With the car parked, confirm whether the tail, brake or another rear lighting function is affected. Match the bulb’s base, contact count and rating to that position before fitting a replacement.","check":"The bulb and lamp position are identified, and power is isolated before disassembly."},{"title":"Reach and remove the holder","body":"Release the side liner retainer in the trunk and pull the liner aside. Grip the holder rather than the wires. Turn the holder a quarter turn to unlock it, then pull it out of the body-mounted lens.","check":"The correct holder is free and the wiring and lens are undamaged."},{"title":"Install the bulb and lock the holder","body":"Press the old bulb gently into its bayonet socket and turn it counterclockwise to release it. Match the new bulb pins to the socket slots, press and turn it into lock. Refit the holder and secure the liner.","check":"The bulb stays seated and the holder locks without forcing it."},{"title":"Verify the lighting","body":"Restore the battery connection and test the affected function. Use a helper or a safe reflection for brake lamps. Check the other functions on that housing and record any remaining warning.","check":"The repaired lamp and the other affected housing functions work before the car is driven."}]}'::jsonb),
('front-door-window-dropped-inspection','03a5a93dfb405f2cf0b84967','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"front-door-window-dropped-inspection","title":"Check a front door window that dropped or sits crooked","system":"body","kind":"inspection","duration":"5–10 min","summary":"Record the glass position and symptoms without cycling a loose window. Identify the right source section for slides, regulator or motor work.","applicability":"Front door glass on Bentley-covered U.S. E34s. This check uses external observations only. Removing the glass, liner or regulator requires a separate procedure and support for the glass.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"512-1, Figs. 1–2 and chapter contents","pdfPages":[353]},"tools":["Light","Camera or service log"],"cautions":["Leave the window switch off if the glass is loose, tilted or jammed. Keep fingers out of the slot and regulator path.","Broken or unsupported glass requires safe handling and support before the door is opened up. Do not slam the door to test it."],"steps":[{"title":"Record where the glass stopped","body":"With the ignition off, record which door is affected and whether the glass is below the seal, tilted or loose. Note any click, motor noise or slow movement that you heard before the failure, without repeating the test on a loose window.","check":"A photo and description identify the door and glass position without operating the mechanism."},{"title":"Separate the glass support from the drive","body":"The manual shows two slides with retaining clips at the lifting-arm connections on the front glass. A loose window is reason to inspect these connections and guides once the glass is safely supported. A silent drive can also require an electrical check. The symptom alone does not identify a failed part.","check":"The report keeps glass support, regulator movement and motor operation separate."},{"title":"Choose the next source and protect the car","body":"Use chapter 512 for front glass and regulator procedures and chapter 411 for door trim access. Arrange safe support or repair if the glass cannot be secured. Share the exact door, symptoms and prior work before ordering a slide, regulator or motor.","check":"The next step identifies what needs inspection and which manual group applies."}]}'::jsonb),
('m50-spark-plug-replacement','fe74da78e64e651cbd52fdfb','{"slug":"m50-spark-plug-replacement","title":"Replace the M50 or M50TU spark plugs","system":"engine","jobSupport":{"reviewedOn":"2026-11-10","sourceSha256":"23032c541d08d764921449cb13751e77847abaeb720abb21e30401e22797322a","requiredParts":["Six matching plugs selected against the installed head/ignition application and current plug-maker guidance"],"conditionalParts":["Damaged boots, coils or connector parts after diagnosis","Valve-cover/plug-well leak repair if standing oil is found"],"stopConditions":["Unconfirmed current plug specification","Standing oil/water or unresolved debris in well","Binding/cross-threading","Damaged boot, coil or connector","New misfire after reassembly"],"steps":[{"number":1,"tools":["Light"],"source":{"printed":"020-10","pdf":32,"href":"/manual/020?pdf=32"}},{"number":2,"tools":["Socket set and ratchet","Straight extension","Camera or labels","Vacuum with a small nozzle"],"source":{"printed":"020-10","pdf":32,"href":"/manual/020?pdf=32"}},{"number":3,"tools":["Spark plug socket","Straight extension"],"source":{"printed":"020-11","pdf":33,"href":"/manual/020?pdf=33"}},{"number":4,"tools":["Spark plug socket","Straight extension","Torque wrench"],"source":{"printed":"020-11","pdf":33,"href":"/manual/020?pdf=33"}},{"number":5,"tools":["Socket set and ratchet","Light"],"source":{"printed":"020-11","pdf":33,"href":"/manual/020?pdf=33"}}],"additionalSources":[{"title":"NGK plated-plug installation: dry threads; no added lubricant","url":"https://ngksparkplugs.com/en/resources/5-things-you-should-know-about-spark-plugs"}]},"engines":["M50","M50TU"],"level":"Intermediate","kind":"replacement","duration":"45–75 min","summary":"Remove the individual coils, inspect the plug wells and replace the plugs with a verified set for the installed cylinder head.","applicability":"U.S. E34 525i with the original M50 or M50TU coil-on-plug system. Use the correct plugs for the actual head and ignition system.","searchTerms":"spark plug change misfire plugs tune up ignition coil m50 m50tu","tools":["Light","Socket set and ratchet","Straight extension","Camera or labels","Vacuum with a small nozzle","Spark plug socket","Torque wrench"],"cautions":["Work with the engine cold and the ignition off. Confirm the plug maker’s installation and torque instructions for the exact plug, especially dry versus lubricated threads.","Stop for pooled oil, damaged threads or cracked coil boots. Keep debris out of open plug holes."],"relatedGuides":["m50-valve-cover-gasket"],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-10–020-11, Table f","pdfPages":[32,33]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Confirm plug fit and reach","body":"Match the plug part number, seat and gap specification to the installed engine. Check the plug maker’s guidance before adjusting a fine-wire electrode.","check":"All six plugs match the application and the correct installation specification is on hand."},{"title":"Expose the coils and record their wiring","body":"Remove the coil cover. Note the connectors, ground straps and brackets. Release the connectors using their catches and lift each coil straight up after removing its hardware. Label the cylinders from the front of the engine.","check":"No coil boot or harness terminal is torn and grounds are accounted for."},{"title":"Inspect each well before removing the plug","body":"Look for standing oil, water and grit. Clean the well before opening it. Use a straight plug socket and extension. Keep the removed plugs in cylinder order if diagnosing a misfire.","check":"The wells are clean and plug condition can be traced to a cylinder."},{"title":"Start threads by hand and seat the plugs","body":"Lower each plug into the well with the socket and start it by hand. If it binds, back it out and inspect the threads. Use the current plug maker’s torque and thread-condition instructions for the exact replacement. Bentley’s historical 30 Nm figure assumes lightly oiled threads; it must not be transferred to a plated plug that the maker specifies installing dry. NGK instructs that its plated plugs receive no added lubricant or anti-seize.","check":"The plugs are seated without cross-threading and tightened using the exact plug’s specified installation condition."},{"title":"Reconnect and check idle","body":"Seat each coil boot, refit coil hardware and grounds, latch the connectors and replace the cover. Start the engine and check for a steady idle. If it misfires, shut down and inspect the affected coil connections and plug fit before running it again.","check":"All connectors are latched and there is no new misfire."}]}'::jsonb),
('m50-valve-cover-gasket','15896564ee7a2026775f9995','{"slug":"m50-valve-cover-gasket","title":"Replace the M50 valve-cover gasket","system":"engine","jobSupport":{"reviewedOn":"2026-11-10","sourceSha256":"23032c541d08d764921449cb13751e77847abaeb720abb21e30401e22797322a","requiredParts":["Matching perimeter gasket","Matching plug-well seals"],"conditionalParts":["Correct fastener insulators/grommets if deteriorated or required by the selected kit instructions","Breather fitting/connector or cover only if damage is found","Sealant only at locations and cure conditions specified for the actual gasket/cover product"],"stopConditions":["Wrong/uncertain cover or kit","Cracked/distorted cover or damaged mating face","Brittle fitting that cannot release normally","Unremoved fastener or force required to lift cover","Missing ground/bracket/hardware record","Gasket will not remain seated","Continued oil leak or abnormal running"],"steps":[{"number":1,"tools":["Light and inspection mirror","Lint-free cloths"],"source":{"printed":"116-3","pdf":101,"href":"/manual/116?pdf=101"}},{"number":2,"tools":["Socket set and ratchet","Straight extension","Camera or labels"],"source":{"printed":"116-3","pdf":101,"href":"/manual/116?pdf=101"}},{"number":3,"tools":["Socket set and ratchet","Non-marring scraper","Lint-free cloths"],"source":{"printed":"116-4","pdf":102,"href":"/manual/116?pdf=102"}},{"number":4,"tools":["Light and inspection mirror"],"source":{"printed":"116-4","pdf":102,"href":"/manual/116?pdf=102"}},{"number":5,"tools":["Low-range torque wrench","Socket set and ratchet","Light and inspection mirror"],"source":{"printed":"116-4","pdf":102,"href":"/manual/116?pdf=102"}}]},"engines":["M50","M50TU"],"level":"Intermediate","kind":"replacement","duration":"1–3 hours","summary":"Reseal the factory cam cover and spark plug wells while preserving coil grounds, cover seals and the specified joint treatment.","applicability":"Bentley-covered E34 525i with an original M50/M50TU head and cover. Verify the gasket kit, cover type and applicable sealing points. Oil from above the cover or a damaged cover needs a separate repair.","searchTerms":"valve cover cam cover rocker cover gasket plug wells oil leak m50","tools":["Light and inspection mirror","Lint-free cloths","Socket set and ratchet","Straight extension","Camera or labels","Non-marring scraper","Low-range torque wrench"],"cautions":["Work cold with the battery isolated according to the vehicle procedure. Keep tools, old gasket and solvent clear of exposed valve gear.","A gasket cannot correct a distorted cover or a damaged sealing face."],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"116-3–116-4, M50 cylinder head cover","pdfPages":[101,102]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Verify the leak and gather matching seals","body":"Clean the suspected area and trace fresh oil. Identify the perimeter seal, plug-well seals and fastener insulators against the actual cover before disassembly.","check":"The leak points to the cover joint or plug wells and the kit fits the cover."},{"title":"Disconnect cover attachments","body":"Remove the covers and ignition coils. Photograph the ground straps and their studs, release the breather at its fitting, and move the wiring aside with support. Record fastener insulator placement.","check":"The harness, grounds and breather are free without breaking a fitting."},{"title":"Lift the cover and prepare the mating surfaces","body":"Lift the cover evenly and remove the seals. Inspect the cover, plug-well grooves and head joints. Use a non-marring tool and keep old sealant out of the head. Clean and dry the sealing faces.","check":"The groove and surfaces are clean, with no cracks or damaged sealing edge."},{"title":"Install seals and seat the cover","body":"Install the perimeter and well seals without stretching. Use sealant only where the gasket or vehicle instructions specify it. Lower the cover squarely and verify that the rear gasket contour and well seals stay seated.","check":"The gasket remains in the groove all the way around and no wire is trapped."},{"title":"Tighten and confirm the repair","body":"Refit the insulators and tighten the source-matching cover hardware progressively and evenly to the listed 10 Nm. Restore every ground, coil and breather connection. Observe any sealant cure interval, then check the perimeter and wells for fresh oil and recheck after a heat cycle.","check":"The engine runs normally and the repaired seam stays dry."}]}'::jsonb),
('m50tu-vanos-diagnosis','0431eb16ffbf8efa5453bf0c','{"slug":"m50tu-vanos-diagnosis","title":"Diagnose M50TU single VANOS travel","system":"engine","engines":["M50TU"],"level":"Advanced","kind":"inspection","duration":"2–4 hours","summary":"Separate a solenoid command problem, insufficient actuator travel and incorrect mechanical indexing on the E34 single-VANOS system.","applicability":"U.S. E34 525i M50TU with factory single intake VANOS. The engine-off air-actuation test needs the specified tools and polarity. A swapped engine requires its own test specifications.","searchTerms":"vanos rattle ticking no low end power single vanos check solenoid test m50tu timing oil leak","tools":["BMW 11 2 300 TDC pin","BMW 11 3 450 air fitting and regulated air","BMW 12 6 410 test lead","Meter","Caliper or depth gauge","New oil feed seals"],"cautions":["Keep the engine off. Remove all locking fixtures before any crank attempt. Confirm electrical polarity at the connector because reversed power can destroy the internal diode.","Use the manual’s regulated-air setup and limits. Contain escaping oil and protect eyes."],"relatedGuides":["m50tu-single-vanos-service"],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"117-16–117-18, Figs. 35–37","pdfPages":[136,137,138]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Identify the symptom before taking the engine apart","body":"Confirm a single-VANOS M50TU. Record cold and warm behavior, oil level, timing work and stored DME faults. A rattle or low-end hesitation can have several causes. Check the connector and oil feed for obvious damage first.","check":"Engine, symptom and baseline electrical or oil-feed observations are recorded."},{"title":"Expose the timing reference and lock crank TDC","body":"Remove the coils, cover and intake-cam oil baffle as shown in the source. Rotate the engine by hand to cylinder 1 compression TDC and insert the correct pin into the flywheel or drive plate. Confirm actual engagement.","check":"Crank timing and cylinder 1 lobe position agree and the pin is fully engaged."},{"title":"Connect the air adapter and measure baseline position","body":"Contain oil at the feed fitting. Replace the feed connection temporarily with the manual’s air adapter and regulated supply. Use 30–115 psi at the source’s regulated air fitting. Measure between the trigger plate edge and the same secondary-tensioner reference face shown in Fig. 37.","check":"The setup is stable, pressure is within the source range and the baseline is written down."},{"title":"Command the solenoid and compare travel","body":"Verify polarity at the vehicle plug and through the test lead. Apply the specified test connection and measure again from the identical reference face. Bentley calls for at least 8.5 mm change. Compare click, actual travel and repeatability separately.","check":"The result records both distances and the observed motion, or records why the test stopped."},{"title":"Interpret and restore","body":"A click alone leaves travel unproven. For short travel, inspect solenoid and actuator plunger freedom and verify VANOS indexing before condemning the unit. Depressurize, remove the test equipment and pin, and restore the feed with new seals. Refit the cover, grounds and connectors.","check":"Every fixture is removed. The feed is dry after startup and the next action follows the measurements."}]}'::jsonb),
('m50tu-single-vanos-service','75f682f09bf084394b9f9020','{"slug":"m50tu-single-vanos-service","title":"Remove and reinstall M50TU single VANOS","system":"engine","engines":["M50TU"],"level":"Advanced","kind":"replacement","duration":"Half day","summary":"Lock crank and cams, remove the actuator, engage the helical gear correctly and prove mechanical timing before startup.","applicability":"Factory U.S. E34 M50TU single intake VANOS, original timing drive. Use this with 117-18–20 and its figures at the bench. Internal actuator seal replacement is a separate bench operation.","searchTerms":"vanos replacement rebuild seals removal install m50tu intake cam timing lock spline","tools":["BMW 11 2 300 crank pin","BMW 11 3 240 camshaft alignment fixture","BMW 11 3 390 dummy tensioner","E10 socket","Low-range torque tools","New actuator gasket and applicable seals"],"cautions":["Incorrect cam timing can cause valve-to-piston contact. Stop if the locks will not locate, the chain is slack or the crank resists hand rotation.","The primary tensioner plug retains a spring. Use the source order and confirm torques for all fasteners. Bentley’s access-plug metric and imperial values disagree."],"evidence":[{"label":"Beisan Systems single VANOS bench-seal procedure","href":"https://beisansystems.com/single-vanos-6-cyl-e36-e34-e39/"}],"relatedGuides":["m50tu-vanos-diagnosis","m50tu-vanos-piston-seals","m50-valve-cover-gasket"],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"117-18–117-20, Figs. 38–40; 116-3–116-4","pdfPages":[101,102,138,139,140]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Expose the actuator and set cylinder 1 compression TDC","body":"Isolate the battery and remove coil and cover hardware, oil baffle and the rear studs called out by Bentley. Rotate the crank by hand in its normal direction. Check damper mark and cam lobes, then engage the crank pin and cam blocks.","check":"Both locking tools locate at the same compression TDC without being forced."},{"title":"Release the secondary sprocket and remove the unit","body":"Disconnect the oil feed and connector, catch the oil and remove the two access plugs. With timing locked, loosen the four E10 sprocket fasteners through the access points. Compress and pin the secondary tensioner as shown in Fig. 39. Remove the housing fasteners and slide the actuator forward. Stop if it will not release without force.","check":"The cam and crank stayed locked, the secondary tensioner is pinned and the unit came away without prying."},{"title":"Set the installation preload arrangement","body":"Confirm the locks, loose sprocket screws and pinned secondary tensioner. Carefully substitute the dummy primary tensioner and take up slack according to Fig. 40. Clean the mating surface and place the new gasket. Apply the source-specified sealant at the alignment dowels.","check":"The chain has controlled slack and the gasket and dowels are correctly seated."},{"title":"Engage the first available spline","body":"Bottom the piston cup in its housing. Slide the unit inward to engage the internal splines first. Viewed from the front, turn the secondary sprockets to the clockwise stop. Maintain inward pressure and move them counterclockwise only enough to engage the outer splines, then seat the unit.","check":"The housing seats flush without using the nuts to draw it into engagement."},{"title":"Set chain preload and secure the timing","body":"Torque the factory housing’s M6 nuts to 10 Nm and its M8 bolt to 22 Nm. Restore the oil feed with fresh seals and tighten its union to 32 Nm. Release the secondary tensioner and set the dummy primary tensioner to Bentley’s 1.3 Nm. Tighten the four sprocket fasteners alternately in the specified 5 Nm and 22 Nm stages for this M50TU.","check":"The housing and sprocket fasteners are secure and the correct preload was used."},{"title":"Prove timing by hand before reassembly","body":"Remove both locks, turn the crank by hand through at least two full turns and recheck both locks at compression TDC. Stop if either fixture fails to locate. Remove the locks, restore the production tensioner with its piston engaged on the rail and fit the access plugs with verified torque and new seals.","check":"Both locks fit again after rotation, all fixtures are out and the running tensioner is installed."},{"title":"Restore the cover and check oil feed and operation","body":"Reinstall the oil baffle, cover, coil grounds, breather and wiring. Inspect the feed fitting before and after startup. If the timing or operation is in doubt, repeat the engine-off travel test before putting the car back in service.","check":"There is no fresh leak or new abnormal noise and VANOS operation has a documented check."}]}'::jsonb),
('m20-timing-belt','654e9a93bfa07f8ef70c3a30','{"slug":"m20-timing-belt","title":"Replace the M20 timing belt and tensioner","system":"engine","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"Half day","summary":"Expose the factory belt drive, establish cylinder 1 TDC, install the belt with slack at the tensioner and verify the marks through two turns.","applicability":"U.S. 1989–90 E34 525i with the original M20 timing drive. The M50 uses a chain. Confirm the exact belt, tensioner and cooling-system components before removing anything.","searchTerms":"m20 timing belt cam belt cambelt tensioner water pump timing marks replacement","tools":["Matched belt and tensioner","22 mm crank socket for source hardware","Fan wrench and pulley holder","Torque wrench","Coolant recovery pan"],"cautions":["The M20 is an interference engine. Stop for timing marks that will not agree, a broken belt or crank resistance. Avoid moving crank and cam independently with the belt removed.","Work with a cold cooling system and a verified refill/bleed procedure. The fan coupling uses a left-hand thread on this installation."],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"118-1–118-4, Figs. 1–8; 170-5","pdfPages":[141,142,143,144,209]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Prepare access and retain the belt routing record","body":"Disconnect the battery. On a cold engine, capture the coolant and remove the radiator and fan using the appropriate cooling chapter. Record hose and belt routing. Remove the coolant crossover, accessory belts, pulley and the distributor/rotor and brackets that obstruct the timing covers as shown in 118-1–2.","check":"The work area is clear and fasteners, ignition leads and hose positions are labeled."},{"title":"Set and photograph the original timing marks","body":"Remove the upper cover. Turn the crank by its center bolt in the normal direction until the cam sprocket mark and crank TDC mark agree. Remove the peripheral pulley/damper bolts and lower cover as shown. Confirm the crank hub mark against the front cover with the damper removed.","check":"Cam and crank references both indicate cylinder 1 TDC."},{"title":"Unload the old belt and inspect the drive","body":"Loosen the specified tensioner fixings. Push the spring tensioner back and lock it temporarily with the upper bolt. Remove the old belt without moving the sprockets. Control the spring as you remove the old tensioner. On the replacement, seat the spring in both the tensioner hole and the water-pump detent shown in Fig. 6. Inspect the sprockets and pump area for wear, play and leakage.","check":"The timing marks have stayed in position and the tensioner spring and pivot seat correctly."},{"title":"Fit the new belt and release the tensioner","body":"Start at the crank and route counterclockwise around the intermediate and cam sprockets, finishing at the tensioner. Keep the driven span taut and all slack at the tensioner. Release the upper fixing slowly to let the spring take up slack.","check":"The belt teeth are fully seated, the spring is engaged and both marks remain aligned."},{"title":"Hand-turn twice and confirm the marks","body":"Turn the crank clockwise through two complete revolutions using the center bolt. Stop if it binds. At TDC, both marks must agree. Refit the belt if they do not. Tighten the documented tensioner mounting bolts to 22 ± 2 Nm once the marks are correct.","check":"Timing agrees after hand rotation and the tensioner is secured."},{"title":"Reassemble, refill and check for leaks","body":"Seat the damper on its locating pin and refit covers, pulleys, distributor, hoses, accessory belts and fan. Use the appropriate fastener sizes and values in the manual. Refill and bleed using the matched M20 cooling procedure. Confirm no tools remain, then check operation, leakage and temperature.","check":"The car warms normally with no coolant loss or abnormal belt noise."}]}'::jsonb),
('e34-cabin-filter-replacement','6ecc4a024e44fbd1ba41d5ff','{"slug":"e34-cabin-filter-replacement","title":"Replace the HVAC cabin microfilter","system":"electrical","engines":["M20","M30","M50","M50TU","M60"],"level":"Intermediate","kind":"replacement","duration":"45–90 min","summary":"Reach the filter from the glovebox side, remove debris and restore the duct and trim without opening the refrigerant system.","applicability":"Source-matching left-hand-drive E34 with the cabin microfilter housing. Bentley’s maintenance section points to 1991 and later cars. Confirm the housing and access arrangement first.","searchTerms":"cabin air filter pollen microfilter micro filter hvac clogged musty weak vents change","tools":["Correct microfilter","Trim tool","Screwdrivers","Small vacuum","Light"],"cautions":["Follow the battery isolation and airbag precautions before working around passenger-side trim. If the access path would disturb an SRS component or connector, stop and use the matching manual procedure."],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-19; 513-4; 640-13, Fig. 30","pdfPages":[41,360,425]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Confirm the filter housing","body":"Find the matching filter cover in the source and compare your HVAC housing. Note the shape and flow orientation of the replacement element.","check":"The installed case has the service cover and the new element matches."},{"title":"Make space at the glovebox and center console","body":"Remove the glovebox following 513-4 and support any light wiring. Remove the carpeted side trim fasteners and the panel above the glovebox. Keep screws sorted by position.","check":"The duct is accessible and wiring is neither trapped nor carrying the panel weight."},{"title":"Remove the duct and open the housing","body":"Remove the two documented ventilation duct screws and take the duct out of the access path. Release the microfilter cover. Slide the element out and note its orientation.","check":"The old filter is clear of the case and the cover clips are intact."},{"title":"Seat the replacement and verify air delivery","body":"Vacuum accessible debris without pushing it into the evaporator. Seat the filter in the intended direction. Restore the cover, duct, trim and glovebox, reconnect anything isolated and test the blower and vent selection.","check":"The filter cover seals, the duct is seated and airflow returns without trim interference."}]}'::jsonb),
('hood-support-struts','00a704a627350615b71b6596','{"slug":"hood-support-struts","title":"Replace the hood support struts","system":"body","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","kind":"replacement","duration":"20–40 min","summary":"Support the hood independently, release each end clip and verify both struts are locked onto their mounting studs.","applicability":"Bentley-covered E34 with the original clip-retained hood gas struts. Match the replacement length, end fittings and orientation.","searchTerms":"hood shocks bonnet gas pressure strut lift support hood falls","tools":["Matched pair of hood supports","Secure independent hood support and helper","Small flat trim tool","Eye protection"],"cautions":["A weak gas strut can release unexpectedly. Support the hood independently for the entire job and work on one side at a time.","Gas struts are pressurized. Keep them away from heat and do not open the cylinder."],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"410-4, Fig. 10","pdfPages":[336]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Secure the hood fully open","body":"Park on level ground, open the hood and place an independent support that cannot slide off. Keep a helper in position and note the strut orientation and stud condition.","check":"The hood’s weight is held independently and the new struts match."},{"title":"Release one strut at both studs","body":"Raise the retaining clip just enough to unlock the end and slide the socket off its stud. Repeat at the opposite end while supporting the strut. Inspect studs and retainers for damage.","check":"The first strut is free and both mounting studs are sound."},{"title":"Seat and test the replacement ends","body":"Match the original orientation and seat both ends fully. Restore each clip and tug lightly to confirm retention. Repeat on the other side.","check":"All four ends are positively retained."},{"title":"Verify support through the hood travel","body":"With the helper still holding the hood, remove the independent support. Move the hood slowly and check that it stays up and closes without binding. Reinstall the support if it does not.","check":"The hood holds open and closes and latches normally."}]}'::jsonb),
('windshield-washer-pump','6299fa2b7198ff6996b07426','{"slug":"windshield-washer-pump","title":"Replace the windshield washer pump","system":"electrical","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","kind":"replacement","duration":"30–60 min","summary":"Confirm the failed pump, remove it from the front reservoir, renew the grommet as needed and check spray and leakage.","applicability":"Factory front windshield washer reservoir at the right front of the engine bay. The separate Touring rear and optional headlamp washer pumps use different access or parts.","searchTerms":"washer pump windshield washer not spraying reservoir grommet leak nozzle windscreen","tools":["Correct pump and sealing grommet","Catch container","Trim and hose tools","Washer fluid","Meter for circuit checks"],"cautions":["Work with the key off during disassembly and keep hands clear of the wipers when testing. The pump may pull out of the grommet and spill the tank."],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"611-7–611-9, Fig. 22","pdfPages":[393,394,395]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Isolate a pump fault","body":"Verify fluid level, a free hose and nozzles and the correct fuse. Test the pump command with the applicable wiring diagram. A running pump with no spray calls for a hose, nozzle, pickup or leak check.","check":"The front pump is identified and supply and ground are confirmed, or the wiring fault is being handled separately."},{"title":"Disconnect and drain the front reservoir","body":"With ignition off, release the reservoir fasteners as needed for access. Disconnect the pump and level-switch plugs and label the delivery hose. Empty the reservoir into a catch container before releasing the pump.","check":"The tank is supported and the openings can be accessed without tension on the harness."},{"title":"Renew the pump seal and reconnect","body":"Pull the pump from its grommet and inspect the tank opening. Fit a good matching grommet and seat the replacement pump squarely. Reconnect the delivery hose, plugs and reservoir fasteners.","check":"The pump sits flush and the hose and connectors are secure."},{"title":"Verify both spray and sealing","body":"Add fluid and inspect the grommet for leaks. Operate the washer briefly from the driver’s seat. Check the spray and recheck the tank, hose and pump seal.","check":"Both nozzles deliver fluid and the reservoir stays dry on the outside."}]}'::jsonb),
('brake-pad-and-rotor-inspection','a29387f52d32233c1aeb07a1','{"slug":"brake-pad-and-rotor-inspection","title":"Measure brake pad and rotor wear","system":"brakes","engines":["M20","M30","M50","M50TU","M60"],"level":"Intermediate","kind":"inspection","duration":"45–90 min","summary":"Check inner and outer pads and compare rotor measurements with the stamped or verified limit for the installed brakes.","applicability":"Bentley-covered U.S. cars with conventional disc brakes. Identify any nonfactory caliper, pad and rotor before comparing wear figures.","searchTerms":"measure brake pads rotor disc thickness worn inner pad pulsation brakes minimum inspection","tools":["Proper lifting equipment and stands","Light","Pad gauge","Brake disc micrometer","Wheel torque wrench"],"cautions":["If the pedal sinks, fluid is leaking or braking is impaired, arrange recovery. Keep brake dust out of the air and support the vehicle before removing wheels.","Use the installed rotor’s specification. The dash wear indicator samples only selected pads."],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-16; 340-3–340-7, Table b","pdfPages":[38,319,320,321,322,323]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Record symptoms and identify the brakes","body":"Note wheel position, pull, vibration, noise and warnings. Identify rotor dimensions and the actual caliper and pad setup. Obtain the correct wear limit for those parts.","check":"The measurements can be compared with the matching specification."},{"title":"Measure lining separately from the backing plate","body":"With the car safely supported, inspect inner and outer pad linings on both sides of the axle. Look for taper, contamination and uneven wear. If visibility is poor, use the applicable caliper access procedure.","check":"Every inspected pad has a measured lining thickness or a note that it was inaccessible."},{"title":"Measure the disc at multiple points","body":"Read the marked rotor minimum or confirm the matching part specification. Measure the swept disc away from the outer lip at several points and record the smallest value. Record cracking, scoring or heavy corrosion separately.","check":"Disc thickness and surface condition are recorded for each side."},{"title":"Act on the weakest measurement","body":"Compare the actual minima with the proper limits. Uneven pad wear needs a sliding or piston check before parts are replaced. Refit the wheels using the applicable wheel-bolt torque. Keep the car off the road if the brakes are unsafe.","check":"There is a clear repair decision for both sides of the axle."}]}'::jsonb),
('identify-transmission-tag','e3cb5dab87bd95cac366a976','{"slug":"identify-transmission-tag","title":"Identify an E34 gearbox from its tag","system":"drivetrain","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","kind":"reference","duration":"20–45 min","summary":"Read the case tag and match the full gearbox code to factory application, fluid and repair information.","applicability":"U.S. Bentley-covered E34s and the factory gearbox families in group 200. A stamped or tagged donor unit can differ from the chassis’s original transmission.","searchTerms":"gearbox transmission identification tag code getrag zf 4hp22 a4s a5s s5d 250 310 560","tools":["Camera and light","Factory application table","Proper lift if access requires it"],"cautions":["Inspect only from safe access. Use rated lifting equipment and support whenever going under the car."],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"200-1–200-2; 230-1; 240-1","pdfPages":[223,224,231,237]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Record the vehicle and current transmission","body":"Note build date, model, installed engine, body and whether the gearbox or differential has been replaced. Record the shifter pattern and service history as clues.","check":"Original vehicle details and current equipment are recorded separately."},{"title":"Read and photograph the tag","body":"Group 200 locates manual markings near the top of the bellhousing and the automatic plate on the left behind the manual valve lever. Check the actual casting and tag layout. Record the entire code, serial or suffix and any separate fluid label. Clean gently so the markings remain legible.","check":"The complete gearbox identifier is readable or marked as unresolved."},{"title":"Select the matching procedure","body":"Compare the identifier with the applicable gearbox table and the unit’s supplier information. Use the specific manual or automatic service section. For a swap, record flange, shifter carrier and gearbox mount details before ordering parts.","check":"The procedure and fluid are tied to the observed transmission rather than the model badge."}]}'::jsonb),
('manual-transmission-fluid','8019b5b24c3f6d4e62005aba','{"slug":"manual-transmission-fluid","title":"Drain and refill a factory manual gearbox","system":"drivetrain","engines":["M20","M30","M50","M50TU","M60"],"level":"Intermediate","kind":"replacement","duration":"45–90 min","summary":"Identify the manual gearbox and fluid label, open the fill plug first, then fill and set the level with the car level.","applicability":"Factory manual boxes in group 230. Fluid designation and torque depend on the observed gearbox and plug. The fluid capacities page lists the source quantities by code.","searchTerms":"manual transmission fluid gear oil change drain refill atf getrag zf gearbox","tools":["Verified fluid and plug seals","Appropriate plug tools and torque wrench","Pump or fill hose","Drain pan","Level supported lift"],"cautions":["Confirm the fluid label and current specification before draining. Keep the vehicle level and securely supported. Warm lubricant can burn."],"relatedGuides":["identify-transmission-tag"],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"230-1–230-2, Fig. 1","pdfPages":[231,232]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Match the fluid and plug hardware","body":"Read the gearbox and fluid tags. Identify the side fill plug and lower drain plug from the correct source drawing. Obtain the applicable torque and seals before starting.","check":"The observed transmission, fluid, fill plug and drain plug are all confirmed."},{"title":"Check fill access first","body":"Clean around both plugs. Break the fill plug loose before opening the drain. If the fill plug will not release or its threads are damaged, resolve that before draining.","check":"The gearbox can be refilled through the intended opening."},{"title":"Drain and inspect","body":"Drain into a clean pan. Look for excess metal, water or unusual discoloration and record it. Clean the plugs and mating surfaces, then install the drain plug with the correct seal and torque.","check":"The drain is sealed and any unusual debris is documented."},{"title":"Set the level and check the seals","body":"With the car level, fill slowly through the fill opening until the lubricant reaches the specified opening level. Fit and torque the fill plug. Clean the case, check both plugs for leaks, and recheck after a short drive if the gearbox is otherwise serviceable.","check":"The level, fluid type and applied torque are recorded and both plugs are dry."}]}'::jsonb),
('differential-fluid-service','106ab4b878c53b6e1037020d','{"slug":"differential-fluid-service","title":"Service the rear differential oil","system":"drivetrain","engines":["M20","M30","M50","M50TU","M60"],"level":"Intermediate","kind":"replacement","duration":"45–90 min","summary":"Confirm an open or limited-slip unit, renew its lubricant and set the level at the correct fill port.","applicability":"Factory-type E34 final-drive units with separate drain and fill plugs. Identify the installed tag and type, particularly on cars with differential swaps.","searchTerms":"differential diff gear oil drain fill lsd limited slip final drive service","tools":["Approved lubricant for the actual unit","Appropriate plug tool and seals","Fluid pump and pan","Level supported lift"],"cautions":["Keep the vehicle level and safely supported. Identify the plug and seal specification from the installed housing. The maintenance and final-drive tables disagree for the 530i and 535i."],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-8 and 331-4, Fig. 6","pdfPages":[30,316]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Identify the installed differential","body":"Read the tag at the left rear of the housing. Confirm the ratio and open or limited-slip design. A missing tag or aftermarket differential needs identification before lubricant is selected.","check":"The fluid selection is tied to the actual differential."},{"title":"Confirm fill access and drain the oil","body":"Clean both plugs. Loosen the upper fill plug first. Drain through the lower plug into a pan and inspect the drained oil for unusual material. Renew seals as specified.","check":"The fill is accessible and the drain is refitted securely."},{"title":"Fill on a level plane","body":"Pump in the verified fluid until it just reaches and begins to spill from the fill opening as described in 331-4. Let the flow settle and torque the fill plug using the applicable specification.","check":"The level was established at the opening with the car level."},{"title":"Inspect the housing and record the service","body":"Clean around the plugs and check for leakage at them and the output seals. Record the tag, fluid, date and any abnormal debris.","check":"The housing is dry and a future owner can identify the lubricant used."}]}'::jsonb),
('diagnose-blown-fuse','9a040fad7c8921f0ebe0f2f4','{"slug":"diagnose-blown-fuse","title":"Find and test a blown fuse","system":"electrical","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","kind":"inspection","duration":"15–45 min","summary":"Identify the correct panel, test both sides of the fuse and decide whether the circuit needs further diagnosis.","applicability":"Bentley-covered U.S. E34 with the corresponding original panel. Use the installed cover and correct wiring diagram for the exact circuit.","searchTerms":"blown fuse test no power fuse keeps blowing short circuit fusebox multimeter","tools":["Wiring diagram and panel cover","Multimeter","Fuse puller","Matching replacement fuse"],"cautions":["Do not bridge a fuse or increase its rating. If a replacement opens again, stop and find the short or excess load. Avoid probing airbag or unidentified terminals."],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"600-4–600-6; 610-1–610-5","pdfPages":[378,379,380,381,382,383,384,385]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Identify the failed functions","body":"List which devices are out and when the fault occurs. Look up the protected circuit and panel in the fuse reference, then verify the installed cover and wiring.","check":"The correct panel, position, supply state and rating are known."},{"title":"Check both sides of the fuse","body":"With the correct circuit state and a proven ground, measure at both exposed test points when available. Voltage on only one side points to an open fuse. No voltage on either side can mean the circuit has not been powered or the feed is missing.","check":"The reading distinguishes a failed fuse from an upstream supply problem."},{"title":"Confirm continuity with the fuse removed","body":"Turn the ignition and load off. Use the fuse puller and test the removed fuse for continuity if needed. Check its terminals and socket for heat damage or corrosion.","check":"The fuse and holder condition are known."},{"title":"Replace once and verify the circuit","body":"If the fuse is open, fit only the confirmed rating and retest the affected function. If it opens again, leave the circuit off and diagnose the protected branches with the diagram.","check":"The function is restored with the correct fuse, or the recurring fault has been isolated for repair."}]}'::jsonb),
('e34-blower-speed-diagnosis','5fe83252a85b98ac4d1800aa','{"slug":"e34-blower-speed-diagnosis","title":"Diagnose a blower that only works on high","system":"electrical","engines":["M20","M30","M50","M50TU","M60"],"level":"Intermediate","kind":"inspection","duration":"30–90 min","summary":"Identify the heater control system and separate a resistor or final-stage fault from a switch, connector or motor fault.","applicability":"Bentley-covered U.S. E34 HVAC layouts. IHKR II/III use a series resistor on the documented configuration. IHKR I and IHKA use a final-stage unit.","searchTerms":"heater fan blower motor only works high speed resistor sword final stage climate control no heat","tools":["Matching HVAC wiring diagram","Multimeter","Trim tools","Light"],"cautions":["Isolate the battery as applicable before removing trim or a module. Check SRS precautions around the glovebox. Avoid shorting module connectors while measuring."],"relatedGuides":["diagnose-blown-fuse"],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"640-1–640-3, Table a and Figs. 4–5; 610","pdfPages":[381,413,414,415]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Test and record each speed","body":"With the car stationary, test each control position and confirm whether high runs smoothly. A dead motor at every speed, intermittent squeal or a burning smell needs a different branch of diagnosis.","check":"The failing positions and motor behavior are recorded."},{"title":"Identify the installed control system","body":"Check the HVAC layout against Table a, the controls and the connector. Locate the series resistor on the documented left-console access path or the final stage on the glovebox side for the matching variant.","check":"The car’s actual resistor or module and wiring diagram match."},{"title":"Check the path before ordering a module","body":"Verify supply and grounds and inspect the connector for heat or corrosion. Use the exact diagram to compare speed commands and motor output. With the circuit isolated, follow the appropriate resistor or final-stage check.","check":"The fault is localized to a command, connection, module or motor branch."},{"title":"Restore the circuit and retest all speeds","body":"Secure the connector and mount the module in its housing before running it. Test all control positions, listen for motor drag and recheck for heat damage. A dragging motor can damage a replacement controller.","check":"Every speed works or the remaining fault is documented for the next test."}]}'::jsonb),
('m50tu-vanos-piston-seals','b02041e7ff12ed1b4f65d274','{"slug":"m50tu-vanos-piston-seals","title":"Renew the M50TU VANOS piston seals on the bench","system":"engine","engines":["M50TU"],"level":"Advanced","kind":"replacement","duration":"1–2 hours on the bench","summary":"Inspect the actuator bore, fit a matching two-piece piston seal and size it before reinstalling and testing the unit.","applicability":"M50TU single-VANOS actuator already removed using the correct timing fixtures. Confirm the installed part number and seal kit. Bentley covers unit removal and refitting. Beisan documents this internal seal repair.","searchTerms":"vanos rebuild repair seals piston o ring teflon ptfe bench m50tu single actuator","tools":["Matched single-VANOS seal kit","Clean bench and oil catch tray","Seal removal tools","Fresh engine oil","Low-range torque wrench","Seal supplier procedure"],"cautions":["Stop for a scored bore, damaged piston groove or splines, or binding after sizing. Protect precision surfaces during seal removal.","Use the factory timing procedure to reinstall the unit and verify timing before cranking."],"evidence":[{"label":"Beisan Systems single VANOS seal installation and sizing","href":"https://beisansystems.com/single-vanos-6-cyl-e36-e34-e39/"}],"relatedGuides":["m50tu-single-vanos-service","m50tu-vanos-diagnosis"],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"117-18–117-20, actuator removal and installation","pdfPages":[138,139,140]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Drain and open the actuator","body":"Drain residual engine oil into a pan and place the actuator on a clean, padded bench. Remove the cylinder cover fasteners and withdraw the cover with the shaft and piston supported. Inspect the cylinder and piston for marks, play and wear.","check":"The bore and piston are suitable for resealing."},{"title":"Remove both parts of the old seal","body":"Lift or carefully section the old outer ring and remove the underlying elastomer ring. Keep the blade off the groove and piston. Wipe the groove and inspect it in good light.","check":"Both old rings are removed and the groove is clean and undamaged."},{"title":"Fit the energizer and outer ring","body":"Seat the elastomer ring flat and untwisted. Condition the outer ring only as directed by the kit maker, then stretch it evenly just enough to seat above the inner ring. Lubricate the piston, bore and chamfer with clean oil as specified.","check":"Both rings lie correctly in the groove without a twist, cut or folded edge."},{"title":"Size the outer ring and confirm smooth movement","body":"Use the seal maker’s sizing sequence. For the cited Beisan kit, ease the piston into the lubricated cylinder at an angle and square it gradually. Back out and reposition if the ring catches. Let it size in the bore for the supplier’s dwell time before removal and inspection.","check":"The ring is uniformly seated and the piston slides smoothly without shaving material."},{"title":"Close, reinstall and measure travel","body":"Refit the cover using the kit and unit’s specified hardware, gasket and torque. Reinstall with the factory locking and indexing procedure, prove timing by hand and check the oil feed. Repeat the actuator travel test if operation is uncertain.","check":"Mechanical timing, sealing and actuator operation have been checked."}]}'::jsonb),
('factory-sliding-caliper-brake-pads','bda2a26028b48f60bf5acc8f','{"slug":"factory-sliding-caliper-brake-pads","title":"Replace brake pads on factory sliding calipers","system":"brakes","engines":["M20","M30","M50","M50TU","M60"],"level":"Advanced","kind":"replacement","duration":"1–3 hours per axle","summary":"Replace pads as an axle set on the illustrated two-guide-bolt calipers, inspect the piston and rotor, and verify a firm pedal before moving.","applicability":"Bentley 340-4–5 factory floating-caliper design with two capped guide bolts, external anti-rattle clip and an inner pad retained by the piston. Confirm installed front or rear hardware. Use the separate procedure for other calipers and for the rear parking brake.","searchTerms":"replace brake pads front rear brake pads caliper guide bolts wear sensor pad change","tools":["Matching axle pad set and sensor as applicable","Rated lift and supports","Caliper hanger","Piston press","Torque wrench","Rotor micrometer"],"cautions":["A low reservoir, hydraulic leak, binding piston, damaged guide bolt or soft pedal requires diagnosis. The car must be firmly supported before removing wheels.","Keep friction surfaces clean. If a bleed screw or line is opened, use the applicable brake bleeding procedure, including any ASC+T requirements, before moving the car."],"relatedGuides":["brake-pad-and-rotor-inspection","brake-fluid-level-inspection"],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"010-3–010-4; 340-4–340-5, Figs. 2–6","pdfPages":[11,12,320,321]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Verify the caliper, rotor and parts","body":"Match both calipers to the illustrated hardware and confirm pads, sensor, retainers and guide bolts. Measure rotors against their marked or verified minimum before deciding to reuse them.","check":"The caliper type is confirmed and both rotors meet the reuse criteria."},{"title":"Lift, unplug the sensor and release the caliper","body":"Secure the car and remove the axle’s wheels. Remove the guide-bolt caps and bolts. Where fitted, unplug and unclip the wear sensor. Remove the external anti-rattle clip and pull the caliper straight off. Suspend it from the chassis without stressing the hose.","check":"The hose is unstressed, the caliper is secure and no brake pedal operation is possible while it is off."},{"title":"Inspect and retract the piston","body":"Remove the pads and inspect the caliper, hose, piston boot and guide bolts. Retract the piston slowly using the appropriate tool and the hydraulic procedure for the installed ABS system. Monitor reservoir level and keep dirt out. Stop if the piston binds or leaks.","check":"The piston retracts smoothly and the hydraulic circuit is sealed or has a verified bleeding plan."},{"title":"Fit the pads and route the sensor","body":"Fit the outer pad and seat the inner pad’s spring in the piston. Renew the sensor if it triggered or was damaged. Route its lead through the original holders. Use approved brake paste only on indicated contact points. The source’s guide bolts are installed clean and dry.","check":"Pads and clips seat correctly, sensor wiring clears moving parts and friction faces are uncontaminated."},{"title":"Secure the caliper and prove the pedal","body":"For the exact source-shown guide bolts Bentley specifies 35 Nm. Fit the caps and anti-rattle clip, then reassemble both sides and torque wheels to the verified specification. With the car stationary, stroke the pedal to seat the pads and confirm a firm pedal and correct fluid level. Check leaks before a controlled low-speed test and follow the pad maker’s bedding instructions.","check":"Pedal pressure holds, braking is even and no leaks, rubbing or warning remain."}]}'::jsonb),
('factory-manual-clutch-installation','5e8a2bc7786ceb192618bfec','{"slug":"factory-manual-clutch-installation","title":"Replace the clutch with the manual gearbox removed","system":"drivetrain","engines":["M20","M30","M50","M50TU","M60"],"level":"Advanced","kind":"replacement","duration":"2–4 hours after gearbox removal","summary":"Inspect the flywheel and release hardware, center the new disc and install the matched clutch before refitting the transmission.","applicability":"Factory-type E34 manual clutch covered by group 210, after the gearbox has been removed using its specific group 230 procedure. Confirm whether the installed pressure plate has separate manufacturer-specific installation requirements.","searchTerms":"clutch replacement pressure plate flywheel clutch disc install pilot bearing throwout release bearing manual swap","tools":["Matched clutch kit and new fasteners","Flywheel holding fixture","Clutch pilot alignment tool","Torque wrench","Correct lubricant for specified contact points","Transmission jack"],"cautions":["Support the engine and gearbox properly. Do not use transmission bolts to pull a misaligned gearbox against the engine.","Keep lubricant off the friction surfaces and use the new pressure-plate bolts required by the source."],"relatedGuides":["identify-transmission-tag","manual-transmission-fluid"],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"210-4–210-6; 230-5–230-6","pdfPages":[228,229,230,235,236]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Match the clutch stack and lock the flywheel","body":"Record the gearbox code and compare flywheel, disc spline, pressure plate and release hardware. With the gearbox safely removed, secure the flywheel and release the pressure-plate bolts gradually in a uniform pattern while supporting the plate and disc.","check":"The clutch comes off without uncontrolled spring movement and the matching parts are identified."},{"title":"Inspect the flywheel, pilot and release parts","body":"Check the flywheel for scoring, cracking and damaged locating pins. Check the pilot bearing, disc splines, fork, pivot and release bearing. Investigate oil contamination before installing new friction parts. Use new flywheel bolts if the flywheel comes off.","check":"The flywheel and release system are serviceable or their replacement is specified."},{"title":"Center the disc and torque the pressure plate","body":"Clean the mating surfaces and face the disc as marked. Seat the plate on its locating pins and center the disc with a pilot tool. Tighten the new bolts evenly in stages. For the source’s listed fasteners, grade 8.8 is 24 Nm and grade 10.9 is 34 Nm. Verify the installed fasteners and kit instructions.","check":"Disc alignment and bolt grade are confirmed and final tightening is recorded."},{"title":"Refit release hardware and gearbox","body":"Check the bearing guide material before applying lubricant. The source leaves the plastic guide sleeve dry and specifies different treatment for earlier aluminum. Check fork and bearing engagement and renew the six-speed pivot and spring clip where applicable. Remove the locking fixture and refit the supported gearbox.","check":"The bellhousing seats without bolt force and the release hardware is secure."},{"title":"Verify disengagement before road testing","body":"Restore the slave cylinder and hydraulic circuit using group 210, bleed if needed and inspect for leaks. Verify clutch pedal return and disengagement with the vehicle secured. Confirm gear engagement, reverse lamp operation and that there are no abnormal sounds before a controlled test.","check":"The clutch engages and disengages normally with a stable fluid level."}]}'::jsonb),
('e34-525i-five-speed-swap','b8e09c892c7ffd76b982946e','{"kind":"planning","level":"Advanced","duration":"Several hours of planning","track":"swap","slug":"e34-525i-five-speed-swap","title":"Plan an E34 525i five-speed manual swap","system":"drivetrain","engines":["M50","M50TU"],"summary":"Select a matched manual driveline for an automatic M50/M50TU 525i, then work through pedals, hydraulics, wiring and commissioning.","applicability":"U.S. left-hand-drive M50/M50TU 525i. Plan from a comparable factory manual donor. Sedan and Touring shaft and linkage fitment must be verified separately. M20, M30, V8 and RHD donor combinations require their own plan.","searchTerms":"auto automatic to manual transmission swap conversion five speed 5 speed 525i getrag 250 zf 310 320 manual pedal donor touring","tools":["Recipient and donor production dates and gearbox codes","Catalog and matching wiring diagrams","Transmission jack and proper lift","Clutch alignment tool","Driveshaft measurements"],"cautions":["Retain working starter interlock and reverse lamps as applicable. Resolve the circuit using vehicle-specific diagrams and verified wiring, without an unfused starter jumper.","Use the exact source for automatic removal, including converter handling, and support the engine and gearbox independently."],"relatedGuides":["identify-transmission-tag","factory-manual-clutch-installation","manual-transmission-fluid"],"durationBasis":"Estimate for the checks listed here. Build time depends on the car and donor.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"200-2, Table b; 210-2–210-5; 230-5; 240-5–240-11; 250-2; 260-4–260-7","pdfPages":[224,226,228,229,235,241,244,245,256,264,267]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Choose a complete, documented donor set","body":"The period 525i manual table lists ZF S5D 310 Z through the July 1992 transition and Getrag S5D 250 G from that transition. Identify the donor by its tag rather than using the month alone. Record body, gearbox code, output flange, drive flange at the differential and installed shaft length.","check":"A complete recipient/donor matrix exists with every flange and mount verified."},{"title":"Lay out the mechanical parts before taking the car apart","body":"Group gearbox, crossmember and mounts, shifter carrier and selector rod, matched driveshaft and flex disc, flywheel, pilot bearing, clutch and release hardware. Match fasteners by unit and identify single-use hardware. Use a shaft with the correct center bearing position and keep its halves indexed.","check":"Every part is present or separately specified and a shop has resolved any custom shaft work."},{"title":"Plan pedals and clutch hydraulic routing","body":"Confirm the donor’s left-hand-drive brake and clutch pedal arrangement, master-cylinder mounting, reservoir feed, hard line, flexible section and slave. Lay out factory-style routing, clips and heat clearance. Use group 210 for bleeding and verify whether fluid work affects the brake reservoir.","check":"The hydraulic system can be installed and bled without a kink, chafe point or unresolved fitting."},{"title":"Plan removal and fit the manual driveline","body":"Follow the installed automatic’s removal section. With the vehicle and powertrain supported, remove the automatic and its cooler connections as required. Follow the matching clutch and manual-box procedures for the pilot bearing, flywheel, clutch, gearbox and mounts. Fit the shifter and indexed shaft using the driveline procedure.","check":"The gearbox, shifter and shaft fit without interference, and every required torque and fluid spec is recorded."},{"title":"Resolve start, reverse and control-unit behavior","body":"Compare recipient automatic and equivalent manual wiring sheets. Trace the start-enable circuit and manual reverse switch, cruise cancellation if equipped, the automatic controller and any coding or cluster behavior. Prove the final circuit states before applying power.","check":"Starter authorization and reverse lamps work as intended. There are no loose live circuits or unresolved controller faults."},{"title":"Commission from static checks to a short drive","body":"Bleed the clutch and inspect for leaks. Fill the gearbox by tag. With the car secured, verify pedal return, disengagement, gear selection, reverse lights and wiring. Check driveshaft clearance, support and mounting. Only after those pass, perform a controlled low-speed test and inspect for vibration or fluid loss.","check":"The build passes the mechanical and electrical checks and has a dated record of installed parts."}]}'::jsonb),
('e34-540i-six-speed-conversion','72afcd41a0f8fc8f95d0d82d','{"kind":"planning","level":"Advanced","duration":"Several hours of planning","track":"swap","slug":"e34-540i-six-speed-conversion","title":"Plan an E34 540i six-speed conversion","system":"drivetrain","engines":["M60"],"summary":"Build a donor checklist around the E34 540i S6S 560G and verify clutch, shaft, differential and chassis-side interfaces.","applicability":"U.S. E34 540i M60 with factory A5S 560Z automatic as the starting point. Factory 540i six-speed equipment is the reference. Check all part numbers and dimensions for cross-chassis V8 gearbox donors.","searchTerms":"540i six speed manual swap 6 speed 560g getrag 420g 560z automatic conversion m60 v8","tools":["Factory 540i manual and automatic parts lists","Donor gearbox and shaft identifiers","Donor and recipient EWD","Shop lift and transmission jack"],"cautions":["Use the complete V8 clutch and release geometry verified for the chosen gearbox. Shared BMW transmission names do not establish bellhousing or driveline compatibility.","Resolve starter authorization, clutch switches and brake/clutch hydraulic operation before road use."],"relatedGuides":["identify-transmission-tag","factory-manual-clutch-installation","manual-transmission-fluid","e34-525i-five-speed-swap"],"durationBasis":"Estimate for the checks listed here. Build time depends on the car and donor.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"200-1–200-2, Tables a–b; 210; 230-5; 240-9–240-11; 260-4","pdfPages":[223,224,225,229,235,245,246,247,264]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Inventory the V8 transmission set","body":"Identify the installed automatic and the intended six-speed by tag. Compare starter position, input pilot, spline and release travel. Record the donor flywheel, clutch, pressure plate, release bearing, fork, pivot and slave as a complete interface.","check":"The donor is identified and the clutch stack and release travel have a documented match."},{"title":"Match shaft, crossmember and rear gearing","body":"Use the factory manual recipient as a comparison for support location, shifter carrier and gearbox output flange. Measure the shaft installation length, center bearing position and differential flange. Calculate overall gearing with the actual differential and tire circumference.","check":"No shaft or flange dimension is assumed from the donor model name."},{"title":"Lay out hydraulics and controls","body":"Confirm pedal and master mounting, reservoir takeoff, pipe and slave connection. Trace the manual start-enable and reverse-lamp circuits and determine coding requirements from the actual production-date diagrams.","check":"The planned hydraulic and electrical arrangements retain all applicable interlocks."},{"title":"Sequence installation and verification","body":"Pair the A5S removal section with the manual and clutch installation sections. Check fit before final tightening. Verify clutch disengagement and all six gears, reverse lamps, fluid levels and shaft clearance before road testing. Stop for leakage, driveline vibration or fault indications.","check":"The shop has a written installation, verification and rollback plan for this specific car."}]}'::jsonb),
('e34-525i-s52-engine-swap','42ed42e844486491c52e179f','{"kind":"planning","level":"Advanced","duration":"Several hours of planning","track":"swap","slug":"e34-525i-s52-engine-swap","title":"Plan an S52 swap into an M50 E34 525i","system":"engine","engines":["M50","M50TU"],"summary":"Build the recipient-to-donor fitment sheet for sump clearance, cooling, wiring, emissions and first start before buying or removing an engine.","applicability":"Rear-wheel-drive E34 525i with an M50 or M50TU as the recipient and a U.S. S52 donor as the proposed engine. Match actual donor electronics and chassis configuration. This is a documented build plan, with donor-specific wiring and fabrication decisions still required.","searchTerms":"engine swap s52 s50 m52 m50 525i e36 donor oil pan sump pickup dme obd2 wiring swap motor","tools":["Donor vehicle and engine identity","Both wiring diagrams and parts catalogs","Engine hoist and rated supports","Measurement tools","Appropriate scan and oil-pressure test equipment"],"cautions":["Check road-use engine-change and emissions requirements for your jurisdiction before purchasing parts. Keep required emissions and diagnostic systems operational.","Confirm sump-to-crossmember, steering and oil pickup clearance. Verify oil supply before combustion."],"evidence":[{"label":"ASC Fabrics E34 S52 and manual swap build log","href":"https://www.ascfabrics.com/post/e34s52-5"},{"label":"California BAR engine replacement and engine change rules","href":"https://www.bar.ca.gov/engine-changes/"},{"label":"U.S. EPA motor vehicle tampering and aftermarket devices","href":"https://www.epa.gov/enforcement/air-enforcement"}],"relatedGuides":["identify-your-engine","e34-525i-five-speed-swap"],"durationBasis":"Estimate for the checks listed here. Build time depends on the car and donor.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"100-1–100-4; 110-4–110-8; 119-5; 130-20; 170; 200-2","pdfPages":[43,44,62,63,64,65,66,149,188,205,224]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Record both cars and the inspection path","body":"Document the E34’s date, body, steering side and original emissions equipment. Record the S52 donor date, complete engine and harness, DME and immobilizer arrangement, oxygen sensors and catalysts. Verify the local inspection path before committing to a donor.","check":"The complete donor identity, required equipment and inspection requirements are recorded."},{"title":"Prove the oil system and mounting geometry","body":"Compare the E34 front-sump arrangement against the donor pan, pickup, dipstick and oil-pump interfaces. Check pickup depth, clearances and sealing as a system. Confirm mounting arms, engine position, crossmember and steering clearance through expected movement before final fit.","check":"A dimensioned mock-up confirms pan, pickup, mounts and steering clearance."},{"title":"Close the transmission, exhaust and cooling interfaces","body":"Decide which gearbox stays. Verify pilot, flywheel, clutch, starter, driveshaft and differential. Mock up exhaust routing and sensor positions without losing required components. Check heater and radiator hose connections, fan clearance, temperature switch/control and service access.","check":"Every mechanical interface has a donor part reference or documented fabrication drawing."},{"title":"Build and verify a wiring schedule","body":"Compare pin function and connector views in both wiring diagrams. Trace power, grounds, charging, starter request, fuel pump, tachometer, coolant indication, diagnostic connector and immobilizer authorization. Have the schedule checked before applying power.","check":"The agreed wiring retains the required diagnostic and security functions and has no unverified feed or ground."},{"title":"Write the first-start and fault-response plan","body":"Confirm safe oil priming for the donor, pressure monitoring, cooling fill and bleed, fuel leak checks and scan access. Confirm throttle return and accessory routing. Stop on absent pressure, overheating, leaks or unexplained faults, and check cooling and wiring again after warmup.","check":"The car has a signed-off pre-start checklist and documented inspection steps before road use."}]}'::jsonb),
('e34-m60b30-to-b40-swap','dbbfa7d4e2732d6296b7db29','{"kind":"planning","level":"Advanced","duration":"Several hours of planning","track":"swap","slug":"e34-m60b30-to-b40-swap","title":"Plan an M60B30 to M60B40 engine swap","system":"engine","engines":["M60"],"summary":"Compare an E34 530i recipient to the factory E34 540i package and account for the larger engine’s drivetrain, cooling and management requirements.","applicability":"Factory V8 E34 530i recipient and identified M60B40 donor. E34 540i hardware is the comparison set. This guide addresses a V8-to-V8 project. Six-cylinder chassis conversions are a separate engineering job.","searchTerms":"530i 540i v8 engine swap m60b30 m60b40 3.0 4.0 engine transplant","tools":["530i and 540i equipment records","Donor engine identification and condition report","Factory diagrams","Hoist and lift plan"],"cautions":["Use the donor’s engine-management and emissions requirements and verify local rules. Engine fit does not establish clutch, automatic converter, cooling or driveline capacity."],"evidence":[{"label":"California BAR engine replacement and engine change rules","href":"https://www.bar.ca.gov/engine-changes/"},{"label":"U.S. EPA motor vehicle tampering and aftermarket devices","href":"https://www.epa.gov/enforcement/air-enforcement"}],"relatedGuides":["e34-540i-six-speed-conversion","identify-transmission-tag"],"durationBasis":"Estimate for the checks listed here. Build time depends on the car and donor.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"100-1, Table a; 110-12–110-14; 170-9; 200-1–200-2","pdfPages":[43,70,71,72,213,223,224]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Identify the actual V8 donor","body":"Confirm B40 identity and production date, then assess condition before installation. Compare the E34-specific sump, pickup, mounts and accessory bracket package with the donor.","check":"The engine is positively identified and has a condition record and E34 mounting plan."},{"title":"Compare complete 530i and 540i packages","body":"Check engine management, exhaust and emissions, intake and fuel hardware, cooling and fans, gearbox, differential ratio, driveshaft and axle interfaces. Verify brakes and suspension against the intended factory equipment and inspection requirements.","check":"The list names each component that is retained, transferred or requires a verified replacement."},{"title":"Resolve electronics and gearbox before installation","body":"Confirm the actual DME, harness, sensors and immobilizer compatibility. Match the gearbox code, flywheel or flexplate and starter to the engine. Confirm controller and cooler compatibility for automatic installations.","check":"All controls and mechanical interfaces have compatible parts and documented wiring."},{"title":"Set acceptance checks","body":"Use the M60 removal and installation section for shop sequencing. Confirm fuel and coolant tightness, oil pressure, charging, fan operation and diagnostic communication before moving the car. Record inspection and cooling checks through a heat cycle.","check":"The installation plan includes clear stop conditions and inspection requirements."}]}'::jsonb),
('m50tu-vanos-delete-planning','f97d29721a386e2aec660a81','{"kind":"planning","level":"Advanced","duration":"Several hours of planning","track":"mod","slug":"m50tu-vanos-delete-planning","title":"Evaluate a fixed-timing M50TU VANOS delete","system":"engine","engines":["M50TU"],"summary":"Compare restoring single VANOS with a kit-specific fixed-timing build, including cam targets, clearance measurements and engine management.","applicability":"M50TU with a documented single-VANOS elimination kit and a qualified engine builder. The VAC instructions are an example for their specific kit. Check its exact hardware and the cam maker’s specification.","searchTerms":"vanos delete elimination kit fixed cam timing disable vanos m50tu race cam conversion adjustable sprocket","tools":["Kit-specific manufacturer instructions","Cam timing card","Degree wheel and dial indicator","Factory crank and cam alignment tools","Clearance measuring equipment"],"cautions":["Disconnecting the solenoid does not install fixed mechanical timing. Incorrect cam timing or insufficient piston clearance can destroy the engine.","Review emissions and road-use rules before changing timing or calibration. Preserve required diagnostics and controls."],"evidence":[{"label":"VAC Motorsports single VANOS elimination kit instructions","href":"https://store.vacmotorsports.com/articles/INST-VEK-M50.htm"},{"label":"U.S. EPA motor vehicle tampering and aftermarket devices","href":"https://www.epa.gov/enforcement/air-enforcement"}],"relatedGuides":["m50tu-vanos-diagnosis","m50tu-single-vanos-service"],"durationBasis":"Estimate for the checks listed here. Build time depends on the car and donor.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"117-16–117-20, factory single VANOS baseline","pdfPages":[136,137,138,139,140]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Define the reason for changing the system","body":"Use the factory test to establish whether there is a command, travel or mechanical indexing fault. For a camshaft build, record the actual cam and required fixed timing. Compare with restoring the factory system for the same use.","check":"The decision has a measured baseline and a stated performance or reliability goal."},{"title":"Confirm the kit and cam stack","body":"Identify the intake cam, trigger and sprocket. Cross-check the kit hardware and shim stack against the exact installation sheet. Confirm the oil and trigger arrangement the manufacturer expects. Obtain written cam targets and fastener specifications.","check":"Every part and timing target is documented for this engine and cam."},{"title":"Degree the cams and measure clearance","body":"Use the manufacturer’s sequence and verify installed cam position with a degree wheel and indicator. Measure piston-to-valve clearance through the relevant crank angles with the actual head, gasket and cams. Confirm timing again through hand rotation before any starter use.","check":"Measured values meet the cam and build specifications and nothing binds."},{"title":"Verify control behavior and record the result","body":"Confirm the applicable engine calibration, diagnostic behavior and compliance path. Plan oil-pressure, idle and hot restart checks and retain the parts and notes needed to restore the original system.","check":"The build has measured timing, clearance, calibration and inspection records."}]}'::jsonb),
('e34-self-leveling-suspension-conversion','4c7ace13d1fc82816b83f81d','{"kind":"planning","level":"Advanced","duration":"Several hours of planning","track":"mod","slug":"e34-self-leveling-suspension-conversion","title":"Plan a self-leveling suspension delete or repair","system":"suspension","engines":["M20","M30","M50","M50TU","M60"],"summary":"Identify the LAD hydraulic circuit, compare an original-system repair with a spring and damper conversion, and verify retained power steering.","applicability":"E34 with confirmed factory LAD/SLS hardware. Match body, axle load and hydraulic pump layout. Touring and Sedan spring and damper choices must be verified for the specific car.","searchTerms":"sls delete self leveling self levelling lad hydraulic rear suspension shocks accumulators wagon touring conversion coilover","tools":["Hydraulic schematic and equipment tags","Rated lift","Correct spring/damper application data","Ride-height and alignment records"],"cautions":["The hydraulic system can retain pressure with the engine stopped. Use the applicable depressurization procedure. Do not cut, plug or reroute lines without understanding pump flow and steering supply.","Use equipment rated for spring loads and an appropriately qualified installer."],"relatedGuides":["power-steering-fluid-level-inspection"],"durationBasis":"Estimate for the checks listed here. Build time depends on the car and donor.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"300-5; 330-3–330-4 and 330-10–330-13","pdfPages":[275,301,302,308,309,310,311]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Identify the source of the height or ride fault","body":"Record rear ride height at both sides and under known load. Identify regulator link, accumulators, struts and signs of leaks. Compare the existing equipment with the LAD schematic before choosing repair or conversion.","check":"The hydraulic fault and the actual equipment are identified."},{"title":"Map the hydraulic supply and return","body":"Trace the reservoir, pump and circuits supplying the steering and the rear. Record approved fluid and the factory routing. Define what hardware is required to keep steering supplied and how retired lines will be managed safely.","check":"The proposed arrangement has a verified pressure and return path for every retained system."},{"title":"Choose springs, dampers and stops as a set","body":"Select hardware rated for the body and rear axle load. Verify mounts, spring pads, bump stops, wheel travel and loaded ride height. Document the compatible conversion instructions before releasing pressure or lifting the car.","check":"The complete rear assembly is specified for the actual vehicle and intended loads."},{"title":"Measure the completed installation","body":"After the matched procedures are followed, check steering assist, leaks, ride height, travel, tire clearance and alignment with the vehicle safely supported and then under normal load. Record the parts and make the change visible in the service history.","check":"Hydraulics, axle geometry and loaded clearance all pass the inspection."}]}'::jsonb),
('e34-electric-fan-conversion','84bc4b94ee4e18740895588c','{"kind":"planning","level":"Advanced","duration":"Several hours of planning","track":"mod","slug":"e34-electric-fan-conversion","title":"Plan a mechanical fan delete with electric cooling","system":"engine","engines":["M20","M30","M50","M50TU","M60"],"summary":"Treat the electric fan, shroud, relay circuit and failure behavior as a cooling system, with measurable hot-idle checks before road use.","applicability":"E34 with a verified original mechanical fan arrangement and an engineered electric replacement. Match engine, radiator, A/C and existing auxiliary fan wiring. No generic switch temperature or fuse rating applies to all conversions.","searchTerms":"fan delete fan clutch delete mechanical fan electric fan conversion efan spal relay shroud radiator overheating idle","tools":["Fan manufacturer specifications","Vehicle wiring diagram","Current measurement tools","Actual coolant-temperature reading","Clearance measurements"],"cautions":["An auxiliary A/C fan’s presence alone does not demonstrate enough cooling capacity. Verify capacity and clearance before removing the mechanical fan.","Protect wiring near the power source and keep hands clear of fans that can start automatically."],"relatedGuides":["cooling-system-visual-check","cooling-fan-airflow-check","diagnose-blown-fuse"],"durationBasis":"Estimate for the checks listed here. Build time depends on the car and donor.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"170-1–170-4, 170-12; 600-4; 610-1–610-5","pdfPages":[205,206,207,208,216,378,381,382,383,384,385]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Establish the cooling baseline","body":"Confirm radiator, thermostat, cap, coolant circulation and both factory fan functions first. Record coolant behavior at idle and with A/C demand. Repair cooling faults before changing the fan arrangement.","check":"The baseline separates a fan limitation from an existing cooling fault."},{"title":"Verify the fan and shroud package","body":"Measure radiator core and available depth. Use documented fan airflow and current data for a puller or pusher layout. Check the shroud, core sealing, mounts and clearance to belts, hoses and engine movement.","check":"Air is routed through the core and the assembly clears moving parts."},{"title":"Design protected power and control","body":"Size the relay/controller, wiring, grounds and fuse to the fan manufacturer’s current and inrush data. Use an appropriate temperature signal, verify A/C integration and define the behavior if the switch, relay or fan fails.","check":"The circuit is drawn, protected and rated, with defined failure behavior."},{"title":"Prove both operation and recovery","body":"Verify direction, current and switch operation in a stationary test. Monitor actual coolant temperature as the system heats and cycles, including A/C demand as applicable. Stop if temperature climbs out of the verified range, the fan fails to start or wiring overheats. Recheck mounts and wiring after a controlled drive.","check":"Temperature stabilizes in the intended conditions and the verification record includes current and cycle behavior."}]}'::jsonb),
('e30-identify-your-configuration','153fb137c7eb9c1129995fd0','{"slug":"e30-identify-your-configuration","title":"Identify an E30 configuration before ordering parts","system":"engine","engines":["M10","M20","M21","M40","M42","S14"],"level":"Beginner","duration":"15–30 min","durationBasis":"Time to record visible details; obtaining an original build record may take longer.","kind":"reference","summary":"Record the actual engine, body, production details and drivetrain before choosing an E30 source.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 identification only. A model badge is not proof of an installed engine, factory equipment or part compatibility.","source":{"id":"e30-manufacturer-configuration","title":"BMW Group Classic model archive and manufacturer application evidence","section":"Named E30 model entries and type-code rows; no manual page numbers inferred","pdfPages":[]},"evidence":[{"label":"BMW model and type-code evidence","href":"/models"},{"label":"BMW original parts references","href":"https://www.bmwgroup-classic.com/en/services/spare-parts/bmw.html"}],"tools":["Camera","Paper or a device for notes","Original build/service records if available"],"cautions":["Work with the engine off and cool. Do not reach near fans or belts.","Do not publish a full VIN or personal registration details in a public post."],"steps":[{"title":"Record the car and source of each detail","body":"Note the model, body, build month, market and steering. Mark an uncertain detail unknown. Keep factory equipment codes separate from later modifications.","check":"Every recorded value has a document, marking or visible feature behind it."},{"title":"Check the installed engine and drivetrain","body":"Compare engine identification and service records with the manufacturer model evidence. Treat an engine swap separately. The 318i can have different four-cylinder families; M3/320is S14 and 325iX AWD need distinct references.","check":"The selected source matches the installed family or the uncertainty is recorded."},{"title":"Open the correct source and compare the actual item","body":"Use the model/type evidence, then compare the full BMW number, source production restrictions and equipment notes. Preserve the exact source link in your private notes. A similar-looking part or shared engine family does not establish interchange.","check":"No unknown configuration has been turned into a confirmed ordering claim."}]}'::jsonb),
('e30-cold-cooling-inspection','6dcd1a85dae08fa92423ea38','{"slug":"e30-cold-cooling-inspection","title":"E30 cold cooling-system visual inspection","system":"cooling","engines":["M10","M20","M21","M40","M42","S14"],"level":"Beginner","duration":"15–25 min","durationBasis":"Visual inspection estimate; pressure testing or repair is outside this procedure.","kind":"inspection","summary":"With a cold, stopped engine, record visible leaks and identify the installed cooling layout before choosing a repair.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 visual inspection. Pump, expansion tank, hoses and thermostat differ by engine/build; no removal, pressure test or hot-system work is included.","source":{"id":"e30-cooling-reference","title":"E30 cooling reference and manufacturer component listings","section":"Cooling layout and engine-specific component evidence; exact repair-manual locator not yet verified","pdfPages":[]},"evidence":[{"label":"E30 Zone original cooling reference","href":"https://www.e30zone.net/e30wiki/index.php/Cooling"},{"label":"BMW expansion-tank application source","href":"https://shop.bmw.co.uk/product/genuine-radiator-expansion-tank-17-11-1-712-641"}],"tools":["Torch","Camera","Gloves","Paper or a device for notes"],"cautions":["If the engine overheated, stop it and allow it to cool completely. Never open a hot pressurized cooling system.","Keep hands away from fans and belts. Do not start an engine to provoke an overheating symptom."],"steps":[{"title":"Make the inspection safe","body":"Park safely, switch off the engine and wait until it is fully cold. If there was steam, rapid coolant loss or a red temperature reading, arrange assessment rather than continuing to drive.","check":"The engine is off, fully cold and safe to observe."},{"title":"Record the installed layout and visible evidence","body":"Photograph the expansion tank, hose routes and accessible pump/thermostat area without dismantling. Note wet areas, residue, damaged hoses and visible belt condition. Record where evidence begins; a nearby wet component is not automatically the cause.","check":"Notes distinguish a visible observation from a diagnosis."},{"title":"Choose the next verified procedure","body":"Match the installed engine and source application before selecting a pump or thermostat. M20 belt work and M42 cooling work follow different procedures. Use the applicable manual for pressure testing, bleeding and tightening values; these have not been established by a visual check.","check":"The repair source matches the configuration and missing specifications remain explicit."}]}'::jsonb),
('e30-driveshaft-center-support','25abf9d0b220837a6dc386e4','{"slug":"e30-driveshaft-center-support","title":"Inspect the driveshaft center support","system":"drivetrain","engines":["M20"],"level":"Intermediate","duration":"20–40 min inspection","durationBasis":"Estimate for visual checks with safe access. Shaft removal, bearing work and road testing take additional time.","kind":"inspection","summary":"Find the support at the shaft joint, inspect the rubber and mounting bracket, and find the illustrated replacement procedure.","reviewStatus":"draft","sourceChecked":true,"applicability":"Rear-wheel-drive E30 325i with the illustrated two-piece shaft. Confirm flange, bearing and bracket details from your build. The iX and M3 need their own catalog and procedure checks.","source":{"id":"e30-factory-propeller-shaft","title":"BMW E30 Repair Manual · Propeller shaft","section":"26-03 through 26-04 for shaft removal, 26-10 through 26-11 for the center mount","pdfPages":[]},"evidence":[{"label":"BMW center mount replacement · page 26-10","href":"https://e30mpower.com/26%20-%20Propellor%20Shaft/26-10.jpg"},{"label":"BMW center mount replacement · page 26-11","href":"https://e30mpower.com/26%20-%20Propellor%20Shaft/26-11.jpg"}],"tools":["Torch","Inspection mirror","Camera","Lift or rated vehicle supports for underbody access"],"cautions":["Never work underneath a vehicle supported only by a jack.","Let the exhaust cool. Support the shaft before loosening the bracket.","Separation, reassembly and preload require the complete procedure and specified tools."],"steps":[{"title":"Locate the complete center mount","body":"With the vehicle safely supported, identify the bracket at the center joint of the two-piece shaft. Match the bearing, rubber and mounting ears to the catalog callout.","check":"The bracket is distinguished from the front flex disc and the loose bearing."},{"title":"Inspect the rubber and bracket","body":"Look for split or detached rubber, witness marks from contact, and bent or loose mounting ears. Check the nearby flex disc visually as well. Record visible observations before choosing the repair.","check":"Photographs show the support and its location."},{"title":"Match the source before removing the shaft","body":"Check the build date and hardware, then consult the linked BMW removal and replacement pages. Plan to support the shaft and retain the relative alignment of both halves. Use the specified puller and fitting tools, the applicable preload and all tightening values from the procedure.","check":"You have the procedure, tools and applicable specifications for the installed shaft."}]}'::jsonb),
('e30-rear-lamp-bulb','d16a7e54d3c9409c938c8afa','{"slug":"e30-rear-lamp-bulb","title":"Replace a rear lamp bulb","system":"electrical","engines":["M10","M20","M21","M40","M42","S14"],"level":"Beginner","kind":"replacement","duration":"15–25 min","durationBasis":"Estimate for access, replacement and a lamp check on the late coupe.","summary":"Reach the lamp carrier from inside the trunk and replace the bulb for the failed circuit.","reviewStatus":"draft","sourceChecked":true,"applicability":"Late E30 325i coupe with the 1988-on rear lamp carrier. Check the actual lamp, build date and bulb markings. The early body, M3 and some convertibles use different assemblies.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"63-7 · 1988-on rear lamp bulb access","pdfPages":[1192]},"evidence":[{"label":"BMW 1991 325i coupe rear lamp diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/lighting/rear_light.html"},{"label":"See the left rear lamp on the car","href":"/workshop?node=e30body%3Atail-light-left"},{"label":"BMW workshop manual download","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}],"tools":["Flashlight","Correct replacement bulb","Clean cloth","Helper for brake and reverse checks"],"cautions":["Park, set the parking brake and switch the lamps and ignition off before touching the holder.","Let the bulb cool. Avoid forcing the carrier or fitting a different wattage."],"steps":[{"title":"Identify the circuit that failed","body":"Compare the two sides with the parking lights, hazards and brake lamps operated separately. If testing the reverse lights, secure the car and have a helper observe with the engine off.","check":"You know which function and side have failed."},{"title":"Release the trunk-side cover","body":"Open the trunk and turn the fastener on the cover behind the affected lens. Lift out the cover and expose the bulb carrier. Compare the installed layout with the rear lamp diagram.","check":"The carrier is accessible without levering the exterior lens."},{"title":"Match and replace the bulb","body":"Remove the bulb from the affected socket. Match the wattage, base and contact arrangement to the original and the catalog. Check that the contacts and carrier are clean, dry and intact. Fit the matching bulb and refit the cover.","check":"The bulb seats securely and the cover fastens without force."},{"title":"Test every function on that side","body":"Switch the circuits on one at a time with a helper. If a lamp still fails or the carrier is damaged, check the matching wiring diagram and connector before replacing anything else.","check":"The repaired lamp, its neighboring lamps and any check-control warning behave normally."}],"jobSupport":{"reviewedOn":"2026-11-11","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Bulb with the wattage, base and contacts listed for the fitted lamp"],"conditionalParts":["Bulb carrier or gasket if the housing shows damage or water entry"],"stopConditions":["The socket is melted, heavily corroded or wet.","The replacement base or contacts differ from the fitted bulb."],"steps":[{"number":1,"tools":["Helper"],"source":{"printed":"00-16","pdf":23,"href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":2,"tools":["Flashlight"],"source":{"printed":"63-7","pdf":1192,"href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":3,"tools":["Matching bulb","Clean cloth"],"source":{"printed":"63-7","pdf":1192,"href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":4,"tools":["Helper"],"source":{"printed":"00-16","pdf":23,"href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}}]}}'::jsonb),
('e30-oil-service','fc28b7133b2a61cbdfd5b139','{"slug":"e30-oil-service","title":"M20 oil and filter change preparation","system":"engine","engines":["M20"],"level":"Beginner","kind":"reference","duration":"15–25 min preparation","durationBasis":"Time to identify the fitted hardware and gather supplies. Drain and refill time varies.","summary":"Match the filter and drain hardware, then find the factory fill quantities and service checks.","reviewStatus":"draft","sourceChecked":true,"applicability":"US 325i / 325is M20 handbook figures. Identify the installed sump and filter, especially on a swapped engine.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"00-15 · Engine oil service, operation 00 00 249","pdfPages":[22]},"evidence":[{"label":"BMW 325i handbook · filling capacities, p. 84","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=85"},{"label":"BMW 1991 325i oil filter diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/engine/lubrication_system_oil_filter.html"},{"label":"Oil pan and original drain plug diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/engine/oil_pan_oil_level_indicator.html"},{"label":"Find the oil filter and sump in Workshop","href":"/quick-reference/model?focus=oil-change"},{"label":"Oil filler location","href":"/quick-reference/locations?point=oil"}],"tools":["17 mm six-point socket for the listed BMW 11 13 1 273 093 plug","Strap-type oil filter wrench that fits the installed canister (76 mm outside diameter for MANN W 719/15)","Torque wrench that covers the installed plug specification","Drain pan of at least 5 L","Funnel","Gloves and eye protection"],"cautions":["Use level ground for the final oil reading and rated supports if access requires lifting.","Avoid hot oil. Check plug thread and tightening specification against the installed sump."],"steps":[{"title":"Identify the service parts","body":"Compare the fitted filter, drain plug and seal against the two catalog drawings. The listed M12 × 1.5 BMW plug takes a 17 mm socket. Check replacement plug heads and filter canister dimensions before choosing a tool.","check":"The socket seats fully and the filter, drain plug and new seal match the installed parts."},{"title":"Check the handbook fill amount","body":"The 325i handbook lists 4.25 L with the filter changed, or 4.0 L without. Confirm the procedure for the installed sump and use the dipstick for the final level.","check":"You have enough oil and a way to verify the level."},{"title":"Plan the final checks","body":"After following the service procedure, check for leaks at the filter and drain plug. On level ground, allow oil to drain back and recheck the dipstick. Take used oil and the filter to an approved collection point.","check":"The level is in range and the filter and drain plug stay dry."}],"jobSupport":{"reviewedOn":"2026-11-14","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Engine oil to the applicable BMW specification","Matched spin-on oil filter","New drain plug sealing washer"],"conditionalParts":["Replacement plug if the head, threads or sealing face are damaged"],"stopConditions":["The sump or drain plug differs from the catalog and you cannot establish the matching specification.","The plug turns without tightening, or the old filter seal has not come off with the old filter."],"additionalSources":[{"title":"SWG catalog · 17 mm hex for BMW 11 13 1 273 093","url":"https://media.swg.de/Marketing/Katalog/KFZ_KAT_EN_77720040175_Befestigung.pdf"},{"title":"MANN W 719/15 size and fitment","url":"https://www.mann-filter.com/us-en/catalog/search-results/product.html/w719/15_mann-filter.html"}],"steps":[{"number":1,"tools":["17 mm six-point socket for the listed BMW 11 13 1 273 093 plug","Strap-type oil filter wrench that fits the installed canister (76 mm outside diameter for MANN W 719/15)"],"source":{"printed":"00-15","pdf":22,"href":"/manual/00?pdf=22"}},{"number":2,"tools":["Drain pan of at least 5 L","Funnel"],"source":{"printed":"Handbook p. 84","pdf":85,"href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=85"}},{"number":3,"tools":["Gloves and eye protection"],"source":{"printed":"00-15","pdf":22,"href":"/manual/00?pdf=22"}}]}}'::jsonb),
('e30-air-filter','ef3d3cadba0f4edecf9af847','{"slug":"e30-air-filter","title":"Replace the M20 engine air filter","system":"engine","engines":["M20"],"level":"Beginner","kind":"replacement","duration":"10–20 min","durationBasis":"Estimate for an intact stock clip-fastened housing.","summary":"Open the airbox, fit the correct panel filter and check the lid seal.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 325i M20 with the stock clip-fastened airbox. Check that the lid and filter match the catalog before opening.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"13-39 to 13-40 · 13 72 001, replacing the air filter element","pdfPages":[272,273]},"evidence":[{"label":"Open air cleaner and filter on the car","href":"/workshop?reference=e30-325i-coupe-manual&node=e30assembly%3Aengine-bay%3Aair-filter"},{"label":"Find the installed air filter in the OEM catalog","href":"/parts/catalog?part=bmw-13721720861"}],"tools":["Flashlight","Clean lint-free cloth"],"cautions":["Switch the engine off before opening the airbox. Keep dust and loose objects out of the clean side of the intake."],"steps":[{"title":"Open the clips","body":"If the intake funnel traps the lid as shown on page 13-39, turn the funnel a quarter turn and slide it forward. Release the airbox lid clips by hand and lift the lid enough to withdraw the filter. Keep the air meter wiring and duct supported.","check":"The lid lifts without pulling on a wire, duct or clip."},{"title":"Replace the element","body":"Lift the old element out and wipe loose debris from the dirty side of the housing. Seat the new element flat in the same orientation, with its sealing edge fully in the channel.","check":"No corner of the seal is rolled or standing proud."},{"title":"Close and check the airbox","body":"Set the lid squarely onto the filter and close all clips. Refit the intake funnel if you moved it. Check that the outlet duct has stayed seated.","check":"The lid closes flush, the clips hold and both ducts are secure."}],"jobSupport":{"reviewedOn":"2026-11-14","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Panel filter matched to the installed airbox"],"conditionalParts":["Lid clip or intake duct if cracked or unable to seal"],"stopConditions":["The lid binds, the clips are broken, or the new filter does not sit flat."],"steps":[{"number":1,"tools":["Flashlight"],"source":{"printed":"13-39","pdf":272,"href":"/manual/13?pdf=272"}},{"number":2,"tools":["Clean lint-free cloth"],"source":{"printed":"13-39","pdf":272,"href":"/manual/13?pdf=272"}},{"number":3,"tools":["Flashlight"],"source":{"printed":"13-39","pdf":272,"href":"/manual/13?pdf=272"}}]}}'::jsonb),
('e30-wheel-removal','53f48962aec9e91fa4d67936','{"slug":"e30-wheel-removal","title":"Remove or install a wheel","system":"suspension","engines":["M20"],"level":"Beginner","kind":"replacement","duration":"15–25 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"U.S. E30 325i / 325is, stock wheel and bolts described in the owner’s handbook.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. E30 325i / 325is, stock wheel and bolts described in the owner’s handbook.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"36-6 · 36 10 300","pdfPages":[724]},"evidence":[{"label":"BMW · 36-6, wheel removal and installation","href":"/manual/36?pdf=724"},{"label":"BMW E30 torque manual · 36-1 · PDF 144","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"},{"label":"1991 325i coupe · cross-spoke wheel diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/wheels/cross_spoke_styling.html"}],"tools":["Wheel bolt wrench or matching socket, chock and calibrated torque wrench. Use the wheel-lock key if fitted."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Use 110 Nm for the stock wheel and bolts covered by the U.S. handbook. Check the wheel maker’s spec for aftermarket hardware."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":[],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"36-6 · 36 10 300","pdf":724,"href":"/manual/36?pdf=724"}},{"number":2,"tools":[],"source":{"printed":"36-6 · 36 10 300","pdf":724,"href":"/manual/36?pdf=724"}},{"number":3,"tools":[],"source":{"printed":"36-6 · 36 10 300","pdf":724,"href":"/manual/36?pdf=724"}}]},"steps":[{"title":"Chock the car and loosen the bolts","body":"Park on level ground. Loosen each bolt slightly with the wheel on the ground. Raise and support the car at the specified points.","check":"The wheel is off the ground and the car is stable."},{"title":"Inspect the seats and mating faces","body":"Support the wheel while removing the bolts. Clean the flat hub and wheel mating faces. Check that the replacement bolt seat and length match the wheel.","check":"The wheel sits flat against the hub and all bolts start by hand."},{"title":"Tighten in a cross pattern","body":"Snug the bolts evenly in a cross pattern, then use the specified torque with the wheel held against turning.","check":"Every bolt reached the applicable torque."}]}'::jsonb),
('e30-front-brake-pads-discs','02c45eddadc7613b0f5483ca','{"slug":"e30-front-brake-pads-discs","title":"Front brake pads and discs","system":"brakes","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"1–2 hr per axle","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive. 260 × 22 mm discs and Girling sliding calipers with external hex guide-pin bolts.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive. 260 × 22 mm discs and Girling sliding calipers with external hex guide-pin bolts.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"34-4 to 34-5 · front pads and discs","pdfPages":[643,644]},"evidence":[{"label":"BMW · 34-4, front brake pads and caliper","href":"/manual/34?pdf=643"},{"label":"BMW · 34-5, front disc removal","href":"/manual/34?pdf=644"},{"label":"1991 325i coupe · front caliper and pads diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/brakes_pedals/front_wheel_brake_brake_pad_sensor.html"},{"label":"1991 325i coupe · front disc diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/brakes_pedals/front_brake_brake_disc.html"}],"tools":["13 mm socket and thin open-end wrench sized to the Girling guide-pin flats.","19 mm six-point socket for the carrier, 5 mm hex bit for the original disc screw and 17 mm socket for stock wheel bolts.","Caliper hanger, piston press, disc micrometer, rated stands and torque wrench."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Keep grease off the disc and lining. Support the caliper independently of its hose.","Pump the pedal until firm before moving the car. Stop if the pedal sinks, a leak appears or the brakes drag.","Check the caliper design first. This sequence covers the bolt-to-guide-pin design with the 35 Nm fastener."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Matched front pad set and new guide-pin bolts.","Two matching discs if the discs are being replaced."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"34-4 to 34-5 · front pads and discs","pdf":643,"href":"/manual/34?pdf=643"}},{"number":2,"tools":[],"source":{"printed":"34-4 to 34-5 · front pads and discs","pdf":643,"href":"/manual/34?pdf=643"}},{"number":3,"tools":[],"source":{"printed":"34-4 to 34-5 · front pads and discs","pdf":644,"href":"/manual/34?pdf=644"}},{"number":4,"tools":[],"source":{"printed":"34-4 to 34-5 · front pads and discs","pdf":643,"href":"/manual/34?pdf=643"}}]},"steps":[{"title":"Check the caliper and disc","body":"Remove the front wheels. Compare the caliper and guide fasteners to BMW’s illustration. Check the disc with a micrometer and confirm the minimum thickness for that disc.","check":"The guide-pin bolt design, pad set and disc match the installed hardware."},{"title":"Remove the pads","body":"Unplug the left front wear sensor. Counterhold the lower guide pin and remove its self-locking bolt. Pivot the caliper up on the upper guide and support it while removing the pads.","check":"No tension or twist is on the hose."},{"title":"Remove or check the disc","body":"For disc replacement, unbolt the carrier and hang the carrier and caliper together with the hose connected. Remove the disc screw and disc. Clean the hub face, seat the disc and tighten its screw to 16 Nm. Refit the carrier and tighten its lightly oiled bolts to 123 Nm for this rear-wheel-drive application.","check":"The disc sits flat and turns without interference."},{"title":"Install pads and check pedal","body":"Press the piston back with a spreader while watching reservoir level. Fit the pads and sensor, lower the caliper and tighten a new self-locking lower guide-pin bolt to 35 Nm while counterholding the pin. Refit the stock wheels to 110 Nm per the 325i / 325is handbook. Pump the pedal and confirm pedal pressure before a low-speed check.","check":"The pedal is firm and both front brakes operate normally."}]}'::jsonb),
('e30-rear-brake-pads-discs','b4646474531c6feb73dbcf35','{"slug":"e30-rear-brake-pads-discs","title":"Rear brake pads and discs","system":"brakes","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"1–2 hr per axle","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive. Factory rear discs and the capped guide bolts in BMW’s illustration.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive. Factory rear discs and the capped guide bolts in BMW’s illustration.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"34-8 to 34-9 · rear pads and discs","pdfPages":[647,649]},"evidence":[{"label":"BMW · 34-8, rear brake pads and caliper","href":"/manual/34?pdf=647"},{"label":"BMW · 34-9, rear disc removal","href":"/manual/34?pdf=649"},{"label":"1991 325i coupe · rear brake diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/brakes_pedals/rear_wheel_brake_brake_pad_sensor.html"}],"tools":["7 mm hex bit for the factory rear guide bolts.","Disc micrometer, caliper hanger, rated stands and torque wrench."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Keep grease off the disc and lining. Support the caliper independently of its hose.","Pump the pedal until firm before moving the car. Stop if the pedal sinks, a leak appears or the brakes drag.","Chock the car independently of the parking brake. Release that brake before removing the rear discs."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Matched rear pad set.","Two matching discs if the discs are being replaced."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"34-8 to 34-9 · rear pads and discs","pdf":647,"href":"/manual/34?pdf=647"}},{"number":2,"tools":[],"source":{"printed":"34-8 to 34-9 · rear pads and discs","pdf":649,"href":"/manual/34?pdf=649"}},{"number":3,"tools":[],"source":{"printed":"34-8 to 34-9 · rear pads and discs","pdf":649,"href":"/manual/34?pdf=649"}}]},"steps":[{"title":"Remove the pads","body":"Remove the caps and use a 7 mm hex bit on the original guide bolts. Hang the caliper. Note the positions of the pads and retaining spring.","check":"The rear caliper is supported and the pads match the replacements."},{"title":"Fit the rear discs","body":"Remove the carrier and retaining screw. Back off the parking brake shoe adjuster if the disc will not release. Clean the hub face and inspect the shoe linings before seating the new disc.","check":"The disc seats flat and the parking brake shoes stay in place."},{"title":"Refit and check","body":"Tighten the disc screw to 16 Nm, the carrier to 67 Nm and the original 7 mm guide bolts to 30 Nm with −5 Nm tolerance. Restore the parking brake adjustment and pump the service pedal before driving.","check":"Both discs turn freely with the brake released and hold when applied."}]}'::jsonb),
('e30-brake-fluid-flush','65304222a2c127857bf8e39b','{"slug":"e30-brake-fluid-flush","title":"Brake fluid flush and bleeding","system":"brakes","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"45–90 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive. Factory hydraulic brakes. Use the procedure for the installed ABS or non-ABS system.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive. Factory hydraulic brakes. Use the procedure for the installed ABS or non-ABS system.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"34-2 · 34 00 046 / 047","pdfPages":[641]},"evidence":[{"label":"BMW · 34-2, conventional and ABS bleeding","href":"/manual/34?pdf=641"}],"tools":["7 mm or 9 mm six-point bleeder wrench, according to the fitted screw.","Reservoir pressure bleeder, clear hose, catch bottle and low-range torque wrench."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Pump the pedal until firm before moving the car. Stop if the pedal sinks, a leak appears or the brakes drag.","Brake fluid damages paint. Do not let the reservoir run dry or exceed the pressure limit."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Fresh approved brake fluid in a sealed container."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"34-2 · 34 00 046 / 047","pdf":641,"href":"/manual/34?pdf=641"}},{"number":2,"tools":[],"source":{"printed":"34-2 · 34 00 046 / 047","pdf":641,"href":"/manual/34?pdf=641"}},{"number":3,"tools":[],"source":{"printed":"34-2 · 34 00 046 / 047","pdf":641,"href":"/manual/34?pdf=641"}}]},"steps":[{"title":"Identify ABS and prepare the bleeder","body":"Use the fresh fluid specified for the installed brake system. Connect a reservoir pressure bleeder with a sound cap gasket. BMW gives a 2 bar maximum for the pressure equipment on this page.","check":"The bleeder holds pressure without leaks and the reservoir stays supplied."},{"title":"Bleed in the correct sequence","body":"For ABS, follow 34 00 047. Start at the right rear, then left rear, right front and left front. At each wheel, hold the pedal down and open the bleeder. Release the pedal and stroke it fully 12 times. Hold it down, close the bleeder, then release the pedal. For conventional brakes, use 34 00 046 and close each bleeder when the fluid is clear of air.","check":"Fresh, bubble-free fluid emerges from each bleed hose."},{"title":"Close the bleeders and check","body":"Tighten a 7 mm wrench-size bleeder to 5 Nm or a 9 mm one to 6 Nm. Release bleeder pressure before removing the cap, set the reservoir level and check at all four wheels.","check":"No fluid leaks and a held pedal stays firm."}]}'::jsonb),
('e30-front-control-arm','fb71b04fc5378cc3b83a1c68','{"slug":"e30-front-control-arm","title":"Front control arm replacement","system":"suspension","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"1–2 hr per side","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Factory steel wishbones; use the separate procedure for the 325iX or M3.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Factory steel wishbones; use the separate procedure for the 325iX or M3.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"31-6 · front wishbone replacement","pdfPages":[507]},"evidence":[{"label":"BMW · 31-6, front control arm replacement","href":"/manual/31?pdf=507"},{"label":"1991 325i coupe · front wishbone and bushing diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/front_rear_axle/front_axle_support_wishbone.html"}],"tools":["BMW 31 1 110 ball joint separator for the standard strut.","Torque wrench covering 42–85 Nm. Use the socket that fully fits each replacement nut."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Keep both ball-joint tapers and their seats clean and dry. Fit locking hardware that matches each joint."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Wishbone for the correct side and its locking hardware."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"31-6 · front wishbone replacement","pdf":507,"href":"/manual/31?pdf=507"}},{"number":2,"tools":[],"source":{"printed":"31-6 · front wishbone replacement","pdf":507,"href":"/manual/31?pdf=507"}},{"number":3,"tools":[],"source":{"printed":"31-6 · front wishbone replacement","pdf":507,"href":"/manual/31?pdf=507"}}]},"steps":[{"title":"Match the replacement arm","body":"Check the side, steel arm and bushing position against the original. Support the hub so the brake hose cannot be pulled.","check":"The replacement arm, bracket and fasteners match the RWD application."},{"title":"Release the joints and bracket","body":"Remove the inner and outer joint nuts and separate the tapered joint with the factory separator specified for the strut. Unbolt the rear bushing bracket and withdraw the arm.","check":"The dust boots, hub and hose are clear of the tool path."},{"title":"Fit the arm and verify steering","body":"Seat the joints and install the specified locking nuts. Tighten the inner joint to 85 Nm, outer joint to 65 Nm and bracket to 42 Nm. Check for full steering travel and arrange an alignment.","check":"The joints are seated, boots intact and alignment checked before normal use."}]}'::jsonb),
('e30-tie-rod','76dc0bd4a37aaa98a166d94b','{"slug":"e30-tie-rod","title":"Steering tie rod and outer end","system":"suspension","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"1–2 hr per side","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Rack-and-pinion steering. Match the fitted lock plate and the steering damper arrangement.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Rack-and-pinion steering. Match the fitted lock plate and the steering damper arrangement.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"32-8 · 32 21 251","pdfPages":[583]},"evidence":[{"label":"BMW · 32-8, tie rod replacement","href":"/manual/32?pdf=583"},{"label":"1991 325i coupe · steering linkage diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/steering_drive_shaft/steering_linkage_tie_rods.html"}],"tools":["BMW 32 2 070 separator for the outer joint.","BMW 32 2 100 for the standard inner joint, or 32 2 110 for the steering-damper version shown. Use pliers on the lock plate."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Preserve the rack boot seal. A measured starting length still requires alignment."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Tie rod for the installed rack, new securing plate and outer locking hardware."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"32-8 · 32 21 251","pdf":583,"href":"/manual/32?pdf=583"}},{"number":2,"tools":[],"source":{"printed":"32-8 · 32 21 251","pdf":583,"href":"/manual/32?pdf=583"}},{"number":3,"tools":[],"source":{"printed":"32-8 · 32 21 251","pdf":583,"href":"/manual/32?pdf=583"}}]},"steps":[{"title":"Record the existing adjustment","body":"Center the steering and measure the fitted tie rod between repeatable points. Record the length before loosening the adjuster.","check":"A starting length is recorded for the same side of the car."},{"title":"Release the outer and inner joints","body":"Use the extractor for the tapered stud. Release the boot and securing plate, then remove the inner joint using the BMW tool that matches the fitted rack.","check":"The rack threads and boot sealing surfaces are undamaged."},{"title":"Refit, secure and align","body":"Use a new securing plate and tighten the inner joint to 75 Nm. Fit the correct outer locking hardware and tighten the stud to 36.5 ± 3.5 Nm. Set the recorded length, then have toe set and the adjuster clamp tightened to 14 Nm under normal load.","check":"The rack boot is sealed, the steering moves freely and toe is set."}]}'::jsonb),
('e30-front-wheel-bearing','348b69c94a33d1528cd28436','{"slug":"e30-front-wheel-bearing","title":"Front hub and wheel bearing","system":"suspension","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"1–2 hr per side","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. RWD stub axle with a hub and integral bearing. The 325iX bearing is pressed into a different assembly.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. RWD stub axle with a hub and integral bearing. The 325iX bearing is pressed into a different assembly.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"31-10 to 31-10.1 · 31 21 180","pdfPages":[514,515]},"evidence":[{"label":"BMW · 31-10, RWD front hub removal","href":"/manual/31?pdf=514"},{"label":"BMW · 31-10.1, installing the new hub","href":"/manual/31?pdf=515"},{"label":"Baum Tools · front hub sockets, 36 mm and 46 mm","href":"https://www.myclassicparts.com/wp-content/uploads/2021/10/01_BMW_Baum_Tools_Catalogue.pdf"},{"label":"1991 325i coupe · front hub and wheel bearing diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/front_rear_axle/wheel_bearings.html"}],"tools":["36 mm thin-wall six-point socket for the original M24 collar nut (BMW 11 2 180).","BMW 31 2 101 / 102 / 104 hub puller set and 31 2 120 installer, or the correct equivalents.","Torque wrench rated for 290 Nm; staking tool for the new nut."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Keep grease off the disc and lining. Support the caliper independently of its hose.","Use a new collar nut and grease cap. Check the separate 325iX procedure if the hub is driven."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Hub with integral bearing, collar nut and grease cap."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"31-10 to 31-10.1 · 31 21 180","pdf":514,"href":"/manual/31?pdf=514"}},{"number":2,"tools":[],"source":{"printed":"31-10 to 31-10.1 · 31 21 180","pdf":515,"href":"/manual/31?pdf=515"}},{"number":3,"tools":[],"source":{"printed":"31-10 to 31-10.1 · 31 21 180","pdf":515,"href":"/manual/31?pdf=515"}}]},"steps":[{"title":"Expose the RWD hub","body":"Remove the disc and hang the caliper. Lift the grease cap, then release the staking on the M24 collar nut before using a 36 mm thin-wall socket.","check":"The stub axle threads and ABS sensor are undamaged."},{"title":"Pull off the hub and fit the new unit","body":"Use BMW’s puller and installer arrangement. If a bearing race stays on the stub axle, use the specified race puller. Clean and inspect the journal before seating the new hub.","check":"The hub seats fully without hammering through the bearing."},{"title":"Torque, stake and check","body":"Tighten the new collar nut to 290 Nm, stake it and install the cap. Refit the brakes and wheel, check free rotation and verify that there is no bearing play.","check":"The staking is secure and the brake pedal is firm."}]}'::jsonb),
('e30-front-strut','e4b7cd037f0f2a56e024f5f4','{"slug":"e30-front-strut","title":"Front strut, upper mount and damper","system":"suspension","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"2–4 hr per side","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Check the damper and upper mount type before applying shaft torque.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Check the damper and upper mount type before applying shaft torque.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"31-11 to 31-14 · 31 31 000 / 31 32 001","pdfPages":[516,519,520,521]},"evidence":[{"label":"BMW · 31-11, front strut removal","href":"/manual/31?pdf=516"},{"label":"BMW · 31-13, spring compressor and shaft counterhold","href":"/manual/31?pdf=520"},{"label":"BMW · 31-14, retaining ring and parts order","href":"/manual/31?pdf=521"},{"label":"1991 325i coupe · front upper mount diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/front_rear_axle/guide_support_spring_pad_attaching_parts.html"},{"label":"1991 325i coupe · front strut and damper diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/front_rear_axle/front_spring_strut_shock_absorber.html"}],"tools":["BMW 31 3 111 spring compressor with the fitting shown, and 31 3 170 shaft-nut tool with a counterhold.","BMW 31 3 150 or 31 3 180 retaining-ring tool, according to the installed collar."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Never release the shaft nut while the spring bears on the mount. Use a compressor with the correct hooks for the spring."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Matched strut inserts or mount components as required and new upper-mount locking nuts."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"31-11 to 31-14 · 31 31 000 / 31 32 001","pdf":516,"href":"/manual/31?pdf=516"}},{"number":2,"tools":[],"source":{"printed":"31-11 to 31-14 · 31 31 000 / 31 32 001","pdf":520,"href":"/manual/31?pdf=520"}},{"number":3,"tools":[],"source":{"printed":"31-11 to 31-14 · 31 31 000 / 31 32 001","pdf":521,"href":"/manual/31?pdf=521"}},{"number":4,"tools":[],"source":{"printed":"31-11 to 31-14 · 31 31 000 / 31 32 001","pdf":516,"href":"/manual/31?pdf=516"}}]},"steps":[{"title":"Remove the strut assembly","body":"Support the hub and brake caliper. Disconnect the links shown on page 31-11 and clear the hose and sensor leads before releasing the top mount.","check":"The assembly comes out without pulling on brake or sensor lines."},{"title":"Unload the upper mount","body":"Check the parts order on 31-12. Fit BMW 31 3 111 or a correctly sized equivalent and compress the spring until it is free of the mount. Counterhold the shaft with the tool specified for its head.","check":"The compressor is seated securely and the spring is unloaded at its ends."},{"title":"Replace the insert or upper mount","body":"Use the established collar tool for the cartridge. Assemble the isolators, spring and mount in BMW’s order. Select the shaft-nut torque using the actual internal or external hex design from the specification card.","check":"The spring ends are in their seats before the compressor is removed."},{"title":"Install and check alignment","body":"Install the complete strut with new locking nuts at the upper body mount and tighten them to 22 Nm. Use the linked front axle specifications for the joints disturbed during removal. Restore hose support and have alignment checked.","check":"Steering moves freely with no contact or tension on the leads."}]}'::jsonb),
('e30-m20-spark-plugs','89cd1d43bd4281a318fd65e7','{"slug":"e30-m20-spark-plugs","title":"M20 spark plugs","system":"engine","engines":["M20"],"level":"Beginner","kind":"replacement","duration":"30–60 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"E30 325i with the original M20 and factory-type M14 × 1.25 plugs. Install six of the same type.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 325i with the original M20 and factory-type M14 × 1.25 plugs. Install six of the same type.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"12 12 · M20 ignition wires and spark plugs","pdfPages":[]},"evidence":[{"label":"BMW TIS 12 12 · Spark plugs","href":"https://workshop-manuals.com/bmw/3_series_e30/325i_m20_sal/4_tightening_torques/12__engine_electrical_system_(m20)/12__ignition_wires_spark_plugs/1_azd__spark_plugs/"},{"label":"BMW E30 torque manual · 12-2 · PDF 39","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"},{"label":"BMW spark plug application chart","href":"https://bmwtechinfo.bmwgroup.com/sib_attachments/B120199SparkPlugChart.pdf"},{"label":"NGK · ZGR5A socket size","href":"https://www.ngkntk.com/part-finder/quad-atv/spark-plugs/bush-hog/trail-hunter-zgr5a-1/"},{"label":"BMW · tool 12 1 180","href":"https://workshop-manuals.com/bmw/3_series_e30/325i_m20_conver/10_special_tool/12__engine_electrical_system_(m20)/1_swz__pliers/"},{"label":"1991 325i sedan · ignition wiring diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-sedan_e30/engine_electrical_system/ignition_wiring.html"}],"tools":["21 mm (13/16 in nominal) spark plug socket for the listed Bosch W-series plugs.","20.8 mm (13/16 in) deep spark plug socket for NGK ZGR5A.","BMW 12 1 180 plug-lead pliers for original connectors. Pull by the boot."],"cautions":["Let the engine cool before working around the plugs, fan or exhaust.","Work on one lead at a time. Start the new plug by hand to protect the head threads."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Six identical spark plugs approved for the installed M20."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"BMW TIS 12 12 · Spark plugs","href":"https://workshop-manuals.com/bmw/3_series_e30/325i_m20_sal/4_tightening_torques/12__engine_electrical_system_(m20)/12__ignition_wires_spark_plugs/1_azd__spark_plugs/"}},{"number":2,"tools":[],"source":{"printed":"BMW TIS 12 12 · Spark plugs","href":"https://workshop-manuals.com/bmw/3_series_e30/325i_m20_sal/4_tightening_torques/12__engine_electrical_system_(m20)/12__ignition_wires_spark_plugs/1_azd__spark_plugs/"}},{"number":3,"tools":[],"source":{"printed":"BMW TIS 12 12 · Spark plugs","href":"https://workshop-manuals.com/bmw/3_series_e30/325i_m20_sal/4_tightening_torques/12__engine_electrical_system_(m20)/12__ignition_wires_spark_plugs/1_azd__spark_plugs/"}}]},"steps":[{"title":"Identify the plug and socket","body":"Match the factory application before opening the plug boxes. Use a 21 mm deep spark plug socket for the listed Bosch W-series plugs or 20.8 mm (13/16 in) for NGK ZGR5A. Check the gap only where the plug maker permits adjustment.","check":"All six plugs are the same approved type."},{"title":"Remove and inspect","body":"Pull each connector by its boot with the specified plug-lead pliers. Clear grit from around the plug before removing it. Record the condition by cylinder if the old plugs show unusual deposits.","check":"The plug holes are clean and the leads remain in firing order."},{"title":"Install and check","body":"Install the plugs by hand, then tighten the clean, dry factory-type M14 plugs to 30 ± 3 Nm, subject to the replacement plug’s installation instructions. Refit the connector fully and check for a smooth idle after all six are installed.","check":"Every boot is seated and the engine runs evenly."}]}'::jsonb),
('e30-m20-alternator-terminals','0a3c8eb9396bcabf5e2df710','{"slug":"e30-m20-alternator-terminals","title":"M20 alternator terminals","system":"electrical","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"25–45 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"12 31 · M20 alternator terminals","pdfPages":[]},"evidence":[{"label":"BMW E30 torque manual · 12-5 · PDF 42","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"},{"label":"1989 BMW 325i ETM · charging circuit","href":"https://www.e30club.ru/stuff/electric/e30_89.pdf#page=29"},{"label":"1991 325i coupe · alternator diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/engine_electrical_system/alternator.html"}],"tools":["13 mm six-point socket for a standard M8 B+ hex nut. Match the D+ nut on the fitted alternator.","Low-range torque wrench covering 5–13 Nm."],"cautions":["Let the engine cool before working around the plugs, fan or exhaust.","Disconnect the battery negative cable before touching B+. Do not bridge a live output terminal to the case."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":[],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"BMW E30 torque manual · 12-5 · PDF 42","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":2,"tools":[],"source":{"printed":"BMW E30 torque manual · 12-5 · PDF 42","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":3,"tools":[],"source":{"printed":"BMW E30 torque manual · 12-5 · PDF 42","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}}]},"steps":[{"title":"Identify the terminals","body":"Use the matching electrical diagram and alternator markings to distinguish B+ from D+. Photograph the cable positions before disconnecting anything.","check":"The alternator label and both terminal markings are readable."},{"title":"Refit and tighten","body":"Clean the mating faces and reinstall the leads without letting the studs turn. Use 13 Nm on factory M20 B+ and 5 Nm on D+ after confirming the alternator type.","check":"Both leads sit flat and the terminal insulation is intact."},{"title":"Restore insulation and test","body":"Refit the B+ cover before reconnecting the battery. Verify that the charge warning lamp comes on with ignition and goes out after starting.","check":"The wiring is covered and the warning lamp behaves normally."}]}'::jsonb),
('e30-manual-gearbox-fluid','9ba36eec89f2fb1608e2413e','{"slug":"e30-manual-gearbox-fluid","title":"Getrag 260 manual gearbox oil","system":"drivetrain","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"45–75 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive. Identify the original Getrag 260/5 and read the fluid label on the installed case.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive. Identify the original Getrag 260/5 and read the fluid label on the installed case.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"00 11 229 · Manual transmission oil change","pdfPages":[]},"evidence":[{"label":"BMW · 00 11 229, manual gearbox oil change","href":"https://workshop-manuals.com/bmw/3_series_e36/325i_m50_coupe/2_repair_instructions/0__maintenance_and_general_data/64_ra__oil_change_in_manual_transmission/"},{"label":"BMW E30 torque manual · 23-2 · PDF 71","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"},{"label":"1991 325i coupe · Getrag 260 housing and plug diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/manual_transmission/housing_attaching_parts_getrag_260_5_50.html"}],"tools":["Oil pump or filling hose, drain pan, level supported lift and torque wrench. Match the socket or hex bit to the installed plugs."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Identify the original Getrag 260 and its fluid label before draining. Similar cases may use different fluids."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Approved fluid identified from the Getrag case label."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"BMW · 00 11 229, manual gearbox oil change","href":"https://workshop-manuals.com/bmw/3_series_e36/325i_m50_coupe/2_repair_instructions/0__maintenance_and_general_data/64_ra__oil_change_in_manual_transmission/"}},{"number":2,"tools":[],"source":{"printed":"BMW · 00 11 229, manual gearbox oil change","href":"https://workshop-manuals.com/bmw/3_series_e36/325i_m50_coupe/2_repair_instructions/0__maintenance_and_general_data/64_ra__oil_change_in_manual_transmission/"}},{"number":3,"tools":[],"source":{"printed":"BMW · 00 11 229, manual gearbox oil change","href":"https://workshop-manuals.com/bmw/3_series_e36/325i_m50_coupe/2_repair_instructions/0__maintenance_and_general_data/64_ra__oil_change_in_manual_transmission/"}}]},"steps":[{"title":"Confirm the fluid and access","body":"Check the case label and identify both plugs. Support the car level and confirm the fill plug can be removed.","check":"You have the correct fluid and can refill the gearbox."},{"title":"Drain the gearbox","body":"Remove the lower plug and collect the old fluid. Clean the magnet, inspect for large debris and refit the original-style drain plug at 50 Nm.","check":"The plug and mating face are clean and the threads are sound."},{"title":"Refill at the lower edge of the fill opening","body":"With the vehicle level, pump in the approved fluid until it reaches the lower edge of the opening. Seal the original fill plug at 50 Nm and clean the case so a leak is visible.","check":"The fill level is correct and both plugs stay dry."}]}'::jsonb),
('e30-4hp22-sump','bb9fe3376ec9b7f94fdb4dc4','{"slug":"e30-4hp22-sump","title":"ZF 4HP22 transmission pan and fluid","system":"drivetrain","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"1–2 hr","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive. ZF 4HP22 with the original dipstick, drain plug and steel pan. Read the gearbox plate and fluid recommendation first.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive. ZF 4HP22 with the original dipstick, drain plug and steel pan. Read the gearbox plate and fluid recommendation first.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"24-110 · 24 11 002","pdfPages":[388]},"evidence":[{"label":"BMW · 24-110, 4HP22 oil sump","href":"/manual/24?pdf=388"},{"label":"BMW · 24-113, oil screen and hydraulic control","href":"/manual/24?pdf=392"},{"label":"1991 325i coupe · 4HP22 pan and housing diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/automatic_transmission/housing_parts_lubrication_system_zf_4hp22_24.html"}],"tools":["BMW 24 0 080 filling funnel, drain pan and level lift.","Low-range torque wrench covering 7–16 Nm. Check the installed pan screws and plug before choosing sockets."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Let hot fluid cool before draining. Stop if the fluid is burnt or contains substantial debris. Diagnosis comes before a refill."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Approved ATF for the identified transmission, profile gasket and drain plug seal."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"24-110 · 24 11 002","pdf":388,"href":"/manual/24?pdf=388"}},{"number":2,"tools":[],"source":{"printed":"24-110 · 24 11 002","pdf":388,"href":"/manual/24?pdf=388"}},{"number":3,"tools":[],"source":{"printed":"24-110 · 24 11 002","pdf":388,"href":"/manual/24?pdf=388"}}]},"steps":[{"title":"Identify the pan and drain","body":"Read the transmission tag. Confirm the fitted pan, dipstick, plug and replacement gasket. Drain the ATF with the car supported level.","check":"The drain plug matches the M10 specification and the drained fluid has been inspected."},{"title":"Clean and refit the pan","body":"Disconnect the dipstick tube fitting and remove the pan. Clean the pan and both magnets. Refit them and a new profile gasket with the pan bracket orientation shown in the manual. Use the E30 archive’s 7 Nm for its original M6 pan screws and 16 Nm for the original M10 drain plug.","check":"Both magnets are in place, the gasket has stayed seated and the tube is sealed."},{"title":"Refill and check at temperature","body":"Use the BMW filling funnel and approved fresh ATF. Follow the manual’s dipstick marks for the initial fill. Recheck at about 80 °C on level ground with the selector in P and engine idling.","check":"The level is within the marked range at the specified temperature and the pan and tube are dry."}]}'::jsonb),
('e30-m20-starter-terminals','7bd432651993caf5bc45726f','{"slug":"e30-m20-starter-terminals","title":"M20 starter terminals","system":"electrical","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"25–45 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"12 41 · Starter wiring connections","pdfPages":[]},"evidence":[{"label":"BMW E30 torque manual · 12-6 · PDF 43","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"},{"label":"1989 BMW 325i ETM · manual starter circuit","href":"https://www.e30club.ru/stuff/electric/e30_89.pdf#page=31"},{"label":"1991 325i coupe · starter diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/engine_electrical_system/starter.html"}],"tools":["8 mm, 10 mm and 13 mm six-point sockets for standard M5, M6 and M8 hex nuts, respectively. Confirm the fitted nut profile.","Low-range torque wrench covering 5–12 Nm."],"cautions":["Let the engine cool before working around the plugs, fan or exhaust.","Disconnect the battery negative cable before uncovering the starter supply terminal."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":[],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"BMW E30 torque manual · 12-6 · PDF 43","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":2,"tools":[],"source":{"printed":"BMW E30 torque manual · 12-6 · PDF 43","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":3,"tools":[],"source":{"printed":"BMW E30 torque manual · 12-6 · PDF 43","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}}]},"steps":[{"title":"Identify the starter and its connections","body":"Confirm the starter label and note the wiring position at each marked terminal. Compare the layout to the electrical manual for the installed transmission.","check":"Each cable is identified by the terminal marking on the starter."},{"title":"Inspect and reconnect","body":"Check the terminals for damaged threads and heat discoloration. Clean the cable eyelets and tighten the applicable factory nuts to 12 Nm on 30, 6 Nm on 50 and 5 Nm on 30h when fitted.","check":"The eyelets sit flat and no terminal has twisted."},{"title":"Refit insulation and check starting","body":"Cover the live terminal before reconnecting the battery. Verify that the starter engages and stops as expected when the key is released.","check":"Covers are secure and the starter works normally."}]}'::jsonb),
('e30-front-control-arm-bush','006a93a7a3c4b1a14d8072c8','{"slug":"e30-front-control-arm-bush","title":"Front wishbone bushings","system":"suspension","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"1–2 hr per side","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Use matching left and right bushings and keep their installation marks aligned.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Use matching left and right bushings and keep their installation marks aligned.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"31-8 · 31 12 130","pdfPages":[510]},"evidence":[{"label":"BMW · 31-8, wishbone bushing installation","href":"/manual/31?pdf=510"},{"label":"1991 325i coupe · front wishbone and bushing diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/front_rear_axle/front_axle_support_wishbone.html"}],"tools":["BMW 31 2 130 press fixture for the bushing and bracket; feeler gauge for the factory wear check."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","The bush is a press fit. Stop if the bracket or press fixture cannot be supported squarely."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Matched left and right rubber mounts for the installed wishbones."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"31-8 · 31 12 130","pdf":510,"href":"/manual/31?pdf=510"}},{"number":2,"tools":[],"source":{"printed":"31-8 · 31 12 130","pdf":510,"href":"/manual/31?pdf=510"}},{"number":3,"tools":[],"source":{"printed":"31-8 · 31 12 130","pdf":510,"href":"/manual/31?pdf=510"}}]},"steps":[{"title":"Mark the brackets and check the bushes","body":"Identify each side and record the orientation marks. Confirm the replacement pair is for the six-cylinder RWD arm.","check":"The mounting style and marks match the factory illustration."},{"title":"Press in the new bushes","body":"Support each bracket in BMW 31 2 130 or the matching fixture. Align its mark with the new bush and press the bush in flush from the beveled end as shown.","check":"Each bush is flush and its marks align with its bracket."},{"title":"Refit and verify under normal load","body":"Refit the brackets and tighten them to 42 Nm. With the car at normal load, measure clearance A where the workshop drawing shows it.","check":"Clearance A measures 0.7–1.7 mm on both sides."}]}'::jsonb),
('e30-front-stabilizer','ab11887e3d99ec682d92dff0','{"slug":"e30-front-stabilizer","title":"Front anti-roll bar, links and mounts","system":"suspension","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"1–2 hr","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Link mounts to the control arm; use different specs for an iX or M3 strut-mounted design.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Link mounts to the control arm; use different specs for an iX or M3 strut-mounted design.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"31-17 · 31 35 000","pdfPages":[530]},"evidence":[{"label":"BMW · 31-17, front anti-roll bar","href":"/manual/31?pdf=530"},{"label":"1991 325i coupe · front stabilizer diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/front_rear_axle/stabilizer_front.html"}],"tools":["Counterhold wrench for the flats on the link. Measure the actual bar diameter before buying bushes."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Support the front evenly before disconnecting the bar. Confirm it is free of load at the links."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Matched links or mount bushes for the measured bar diameter if replacing them."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"31-17 · 31 35 000","pdf":530,"href":"/manual/31?pdf=530"}},{"number":2,"tools":[],"source":{"printed":"31-17 · 31 35 000","pdf":530,"href":"/manual/31?pdf=530"}},{"number":3,"tools":[],"source":{"printed":"31-17 · 31 35 000","pdf":530,"href":"/manual/31?pdf=530"}}]},"steps":[{"title":"Identify the layout and measure the bar","body":"Compare the arm-mounted link and clamp positions with the BMW diagram. Measure the bare bar at the bushing seat before ordering rubber mounts.","check":"The link type and bush bore match the car."},{"title":"Release the bar","body":"Counterhold the links while disconnecting both ends. Release the left wishbone bracket as shown for access and remove both bar mounts.","check":"The bar comes out without contacting the steering or brake lines."},{"title":"Install and check clearance","body":"Refit the mounts and links, aligning the bar laterally. Tighten the link-to-bar nuts to 47 Nm and the factory M8 clamp fasteners to 22 Nm. Restore any link pivot bracket disturbed during the work to its 42 Nm specification.","check":"Both links articulate and the bar clears nearby components."}]}'::jsonb),
('e30-coolant-bleeding','fd15e381818ac2d2293b77e0','{"slug":"e30-coolant-bleeding","title":"Fill and bleed the M20 cooling system","system":"cooling","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"30–60 min plus cool-down","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Late rear-wheel-drive E30 325i with the original M20B25 and its separate expansion tank.","reviewStatus":"draft","sourceChecked":true,"applicability":"Late rear-wheel-drive E30 325i with the original M20B25 and its separate expansion tank.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"17-6 · 17 00 039 and late tank on 17-8/1","pdfPages":[332,337]},"evidence":[{"label":"BMW · 17-6, bleeding the M20 cooling system","href":"/manual/17?pdf=332"},{"label":"BMW · 17-8/1, late expansion-tank cold level","href":"/manual/17?pdf=337"},{"label":"1991 325i coupe · expansion tank diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/cooling_exhaust_system/expansion_tank.html"}],"tools":["8 mm wrench for the original thermostat-housing bleed screw.","Low-range torque wrench, clean funnel and drain pan."],"cautions":["Wait for the engine and coolant to cool completely before opening the system. Catch the coolant and keep it away from children and animals.","Stop the engine if the temperature rises abnormally, coolant escapes, or cabin heat drops out when the engine is warm."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Fresh coolant approved for the installed engine, mixed to the required concentration."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"17-6 · 17 00 039 and late tank on 17-8/1","pdf":332,"href":"/manual/17?pdf=332"}},{"number":2,"tools":[],"source":{"printed":"17-6 · 17 00 039 and late tank on 17-8/1","pdf":332,"href":"/manual/17?pdf=332"}},{"number":3,"tools":[],"source":{"printed":"17-6 · 17 00 039 and late tank on 17-8/1","pdf":337,"href":"/manual/17?pdf=337"}}]},"steps":[{"title":"Open the cold system","body":"With the engine off, set the heater to hot. Open the separate expansion tank and loosen the 8 mm thermostat-housing bleed screw.","check":"The open bleeder is at the M20 thermostat housing."},{"title":"Fill slowly and close the bleeder","body":"Pour into the expansion tank until a steady, bubble-free stream reaches the bleed point. Close the original bleeder at 8 Nm. Set the cold level to the molded mark and install the cap.","check":"The bleeder and cap are seated and the tank is at its cold mark."},{"title":"Warm, cool and check again","body":"Run in a well-ventilated area and monitor the gauge and cabin heat. Shut down and let everything cool fully. Recheck the level at about 20 °C and inspect the joints and bleed screw for leaks.","check":"The cold level is stable and there is no leak or overheating."}]}'::jsonb),
('e30-radiator','4cc811d2e2e97b5524e4b573','{"slug":"e30-radiator","title":"Replace the late M20 manual radiator","system":"cooling","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"1–2 hr plus cool-down","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Late rear-wheel-drive E30 325i with the original M20B25 and manual transmission. Check A/C equipment before matching the radiator and thermoswitch.","reviewStatus":"draft","sourceChecked":true,"applicability":"Late rear-wheel-drive E30 325i with the original M20B25 and manual transmission. Check A/C equipment before matching the radiator and thermoswitch.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"17-7 to 17-7/1 · 17 11 000","pdfPages":[333,334]},"relatedGuides":["e30-coolant-bleeding","e30-expansion-tank"],"evidence":[{"label":"BMW · 17-7, radiator removal and installation","href":"/manual/17?pdf=333"},{"label":"BMW · 17-7/1, late radiator and drain position","href":"/manual/17?pdf=334"},{"label":"1991 325i coupe · radiator and supports diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/cooling_exhaust_system/radiator_frame.html"}],"tools":["10 mm socket for an original M6 hex-head mount. Use the drive profile supplied with the actual drain plug.","Low-range torque wrench covering 2.5–10 Nm, clamp driver, catch pan and gloves."],"cautions":["Wait for the engine and coolant to cool completely before opening the system. Catch the coolant and keep it away from children and animals.","This procedure covers the manual-transmission radiator. An automatic has separate cooler lines and requires an ATF level check."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Radiator for the late manual 325i, approved coolant and any failed mounts or hose clamps."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"17-7 to 17-7/1 · 17 11 000","pdf":333,"href":"/manual/17?pdf=333"}},{"number":2,"tools":[],"source":{"printed":"17-7 to 17-7/1 · 17 11 000","pdf":334,"href":"/manual/17?pdf=334"}},{"number":3,"tools":[],"source":{"printed":"17-7 to 17-7/1 · 17 11 000","pdf":334,"href":"/manual/17?pdf=334"}}]},"steps":[{"title":"Drain and free the shroud","body":"Disconnect the battery ground. Catch the coolant at the lower drain. Release the shroud retainers and lift or park the shroud as the manual shows. Disconnect the hoses and any temperature-switch plug.","check":"The radiator can move without pulling hoses or wiring."},{"title":"Lift the radiator and transfer hardware","body":"Remove the upper mounting hardware. Lift the radiator out of its rubber supports. Check the supports, shroud, drain plug and any used temperature-switch seal before transferring hardware.","check":"The replacement core and lower locating pegs match the original."},{"title":"Fit, refill and leak-check","body":"Seat the radiator on its supports. Tighten the original M6 mount to 10 Nm and the catalog-style drain plug to 2.5 Nm. Reconnect the switch, hoses and shroud. Follow the M20 fill and bleed guide before checking for leaks and fan clearance.","check":"The housing is supported and the fan turns without shroud contact."}]}'::jsonb),
('e30-expansion-tank','9a44b2be4c1f0a87e772db4a','{"slug":"e30-expansion-tank","title":"Replace the late M20 expansion tank","system":"cooling","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"30–60 min plus cool-down","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Late rear-wheel-drive E30 325i with the original M20B25 and clip-mounted tank from 09/1987.","reviewStatus":"draft","sourceChecked":true,"applicability":"Late rear-wheel-drive E30 325i with the original M20B25 and clip-mounted tank from 09/1987.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"17-8/1 · 17 11 100","pdfPages":[337]},"relatedGuides":["e30-coolant-bleeding"],"evidence":[{"label":"BMW · 17-8/1, 1988-on expansion tank","href":"/manual/17?pdf=337"},{"label":"1991 325i coupe · expansion tank diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/cooling_exhaust_system/expansion_tank.html"}],"tools":["30 mm wrench for the original level switch.","Low-range torque wrench, clamp driver, 8 mm bleeder wrench and drain pan."],"cautions":["Wait for the engine and coolant to cool completely before opening the system. Catch the coolant and keep it away from children and animals.","Match the late separate tank and all three hose connections before removing the old tank."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Late expansion tank, correct level-switch seal, coolant and replacement clamps for the opened connections."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"17-8/1 · 17 11 100","pdf":337,"href":"/manual/17?pdf=337"}},{"number":2,"tools":[],"source":{"printed":"17-8/1 · 17 11 100","pdf":337,"href":"/manual/17?pdf=337"}},{"number":3,"tools":[],"source":{"printed":"17-8/1 · 17 11 100","pdf":337,"href":"/manual/17?pdf=337"}}]},"steps":[{"title":"Drain to below the tank","body":"Open the cold cap and catch the coolant. Unplug the level switch and label the lower hoses and small vent line before disconnecting them.","check":"Each hose is identified and isolated clear of the mount."},{"title":"Transfer the switch and fit the tank","body":"Unclip the tank from its bracket. With a new seal, tighten the original 30 mm wrench-size level switch to 3 Nm. Engage the replacement tank in all bracket clips and reconnect the original hose routing.","check":"The tank is secure and each hose is fully seated without a kink."},{"title":"Refill and verify","body":"Bleed at the M20 thermostat housing, then recheck the level at about 20 °C. Inspect the tank seams, hose joints and switch seal and check for a low-level warning.","check":"The joint surfaces are dry and the level is stable."}]}'::jsonb),
('e30-m20-timing-belt','9462db52b82fcb5bb73d91fd','{"slug":"e30-m20-timing-belt","title":"M20 timing belt and tensioner","system":"engine","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"3–5 hr","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive. Confirm the fitted sprocket profile and matched roller. The M40 procedure is separate.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive. Confirm the fitted sprocket profile and matched roller. The M40 procedure is separate.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"11-66a to 11-66b · 11 31 110","pdfPages":[110,111]},"relatedGuides":["e30-radiator","e30-coolant-bleeding"],"evidence":[{"label":"BMW · 11-66a, M20 timing belt","href":"/manual/11?pdf=110"},{"label":"BMW · 11-66b, timing marks and belt profile","href":"/manual/11?pdf=111"},{"label":"Continental · M20 timing belt and special tools","href":"https://www.showmethepartsdb3.com/BIN/documents/Continental%20Elite/tb131k1a.pdf"},{"label":"1991 325i coupe · timing parts diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/engine/timing_and_valve_train_tooth_belt.html"}],"tools":["BMW 11 2 150 crankshaft hub holder if the hub is removed. Consult the full procedure before disturbing the hub.","32 mm fan-clutch wrench and pulley holder for the original left-hand coupling."],"cautions":["Wait for the engine and coolant to cool completely before opening the system. Catch the coolant and keep it away from children and animals.","Keep the crank and cam timed together. Stop if the marks disagree, a sprocket profile is uncertain, or the engine binds by hand."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Matching 127-tooth semicircular belt and tensioner for the late M20B25. Inspect the spring and plunger."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"11-66a to 11-66b · 11 31 110","pdf":110,"href":"/manual/11?pdf=110"}},{"number":2,"tools":[],"source":{"printed":"11-66a to 11-66b · 11 31 110","pdf":111,"href":"/manual/11?pdf=111"}},{"number":3,"tools":[],"source":{"printed":"11-66a to 11-66b · 11 31 110","pdf":111,"href":"/manual/11?pdf=111"}},{"number":4,"tools":[],"source":{"printed":"11-66a to 11-66b · 11 31 110","pdf":110,"href":"/manual/11?pdf=110"}}]},"steps":[{"title":"Clear the front of the engine","body":"Use the referenced coolant and belt access procedures to remove the radiator, viscous fan, accessory belts, pump pulley, distributor components and timing covers. Retain the crank sensor and damper orientation. If hub removal is needed, use the BMW hub holder and separate tightening procedure.","check":"The cam and crank timing marks are visible."},{"title":"Set number one to compression TDC","body":"Turn the crankshaft in the normal direction by hand. Verify both marks. Retract the tensioner against its spring and lock it in that position with the bolt indicated in the BMW drawing. Remove the old belt without moving either shaft.","check":"Both marks remain aligned and the late sprockets match the new belt."},{"title":"Fit and tension the new belt","body":"Route the belt from crank to intermediate shaft to cam, then around the tensioner. Keep slack at the tensioner. Release the roller and rotate the crank slowly through two turns. Verify both marks and tighten the two tensioner bolts to the belt maker’s 16 lb-ft (about 22 Nm), in the specified order.","check":"The marks return to alignment with no binding."},{"title":"Refit and check","body":"Refit the covers, sensor, distributor and front drive in their original positions. Restore the cooling system and verify that wiring and hoses clear all moving parts before starting.","check":"Coolant is bled, the engine runs smoothly, and the covers and lines are secure."}]}'::jsonb),
('e30-clutch-bleeding','a043597738e2ccb9867cb697','{"slug":"e30-clutch-bleeding","title":"Bleed the clutch hydraulics","system":"drivetrain","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"30–60 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Late rear-wheel-drive E30 325i with the original M20B25 and hydraulic clutch on the manual transmission.","reviewStatus":"draft","sourceChecked":true,"applicability":"Late rear-wheel-drive E30 325i with the original M20B25 and hydraulic clutch on the manual transmission.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"21-1 · 21 00 006","pdfPages":[358]},"evidence":[{"label":"BMW · 21-1, clutch bleeding","href":"/manual/21?pdf=358"},{"label":"1991 325i coupe · clutch cylinder and vent screw diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/gearshift_clutch/clutch_control.html"}],"tools":["Reservoir pressure bleeder with the fitted cap adapter, clear hose and fluid bottle. Match the six-point wrench to the installed vent screw."],"cautions":["Chock the wheels and use a rated lift or stands. Keep the removed assembly supported separately.","Brake fluid damages paint. Keep the shared reservoir supplied. Never press the pedal while the slave cylinder is detached."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Fresh brake fluid approved for the clutch hydraulics."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"21-1 · 21 00 006","pdf":358,"href":"/manual/21?pdf=358"}},{"number":2,"tools":[],"source":{"printed":"21-1 · 21 00 006","pdf":358,"href":"/manual/21?pdf=358"}},{"number":3,"tools":[],"source":{"printed":"21-1 · 21 00 006","pdf":358,"href":"/manual/21?pdf=358"}}]},"steps":[{"title":"Prepare the reservoir","body":"Inspect the slave and feed for leaks. Fit the pressure-bleeder adapter and support the car with safe access to the transmission.","check":"The reservoir is supplied and the adapter seals."},{"title":"Purge the slave cylinder","body":"Attach the clear hose and open the fitted bleed screw. Work the pedal as shown while fluid runs into the bottle. Close the bleeder when the stream is free of bubbles.","check":"The bleeder is closed and no air is visible in the hose."},{"title":"Verify release travel","body":"Depressurize the bleeder, restore the reservoir cap and check the pedal. If air remains after repeating the procedure, follow BMW’s detached-slave step with the piston controlled. Do not use the pedal during that step.","check":"The clutch disengages consistently and all hydraulic connections stay dry."}]}'::jsonb),
('e30-driveshaft-flex-disc','5741b8f719347ac33e854122','{"slug":"e30-driveshaft-flex-disc","title":"Replace the driveshaft flex disc","system":"drivetrain","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"2–4 hr","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Late rear-wheel-drive E30 325i with the original M20B25 and Getrag 260. Match the flange diameter and bolt grade before choosing hardware.","reviewStatus":"draft","sourceChecked":true,"applicability":"Late rear-wheel-drive E30 325i with the original M20B25 and Getrag 260. Match the flange diameter and bolt grade before choosing hardware.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"26-6 · 26 11 051","pdfPages":[459,460]},"relatedGuides":["e30-driveshaft-center-support"],"evidence":[{"label":"BMW · 26-6, flex disc replacement","href":"/manual/26?pdf=459"},{"label":"BMW · 26-6, flex disc orientation and preload","href":"/manual/26?pdf=460"},{"label":"1991 325i coupe · driveshaft and flex disc diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/steering_drive_shaft/drive_shaft_universal_joint_centre_mounting.html"}],"tools":["BMW 26 1 040 for the sliding ring; socket and counterhold for fitted flange bolts. Use 17 mm for standard M10 hex heads when fitted and verify the actual tool fit.","Rated exhaust and shaft supports, torque wrench, and a ruler for 4–6 mm preload."],"cautions":["Chock the wheels and use a rated lift or stands. Keep the removed assembly supported separately.","Let the exhaust cool. Support the shaft, keep its halves indexed and keep its weight off the fuel crossover line. This guide covers the Getrag 260 layout."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Flex disc for the fitted flange, matching bolts and new self-locking nuts."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"26-6 · 26 11 051","pdf":459,"href":"/manual/26?pdf=459"}},{"number":2,"tools":[],"source":{"printed":"26-6 · 26 11 051","pdf":460,"href":"/manual/26?pdf=460"}},{"number":3,"tools":[],"source":{"printed":"26-6 · 26 11 051","pdf":460,"href":"/manual/26?pdf=460"}}]},"steps":[{"title":"Expose and support the shaft","body":"Remove the required exhaust sections and heat shields. Mark the flange and shaft orientation. Use BMW 26 1 040 to loosen the sliding joint ring.","check":"The shaft and exhaust are supported with the oxygen sensor lead and fuel lines clear."},{"title":"Replace the coupling","body":"Release the transmission flange and support bracket. Move the shaft far enough to clear the centering pin without separating its halves. Install the new disc with the molded arrows toward the flange arms.","check":"Every arrow points to the corresponding flange and the bolts retain their specified orientation."},{"title":"Set preload and torque","body":"Check the centering pilot. Use the torque row for the marked M10 bolt grade. Preload the support 4–6 mm toward the front and tighten its fasteners to 21 Nm. Tighten the fitted RWD sliding ring to 10 Nm after the shaft is installed.","check":"The support is preloaded, the coupling is seated, and the shaft turns freely."}]}'::jsonb),
('e30-rear-shock-absorbers','37f6ce15607f7b67b5fbdfc6','{"slug":"e30-rear-shock-absorbers","title":"Rear shocks and upper mounts","system":"suspension","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"1–2 hr per axle","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive. Conventional rear shocks, without ride-height control.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive. Conventional rear shocks, without ride-height control.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"33-16 · 33 52 000","pdfPages":[636]},"evidence":[{"label":"BMW · 33-16, rear shock replacement","href":"/manual/33?pdf=636"},{"label":"BMW TIS 33 52 · Rear shock tightening table","href":"https://workshop-manuals.com/bmw/3_series_e30/325e_m20_sal/4_tightening_torques/33__rear_axle/52__shock_absorber/1_azd__shock_absorbers/"},{"label":"U.S. 325i · shock and mount diagram","href":"https://www.realoem.com/bmw/enUS/showparts?diagId=33_0327&id=1123-USA---E30-BMW-325i"}],"tools":["Support jack for the trailing arm and rated stands.","Piston-rod counterhold for the fitted shock; size depends on the shaft."],"cautions":["Chock the wheels and use a rated lift or stands. Keep the removed assembly supported separately.","The shock limits trailing-arm droop. Support the arm before undoing the lower bolt and confirm its grade before tightening."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Matched rear shocks or upper mounts as needed, new upper gaskets and applicable self-locking nuts."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"33-16 · 33 52 000","pdf":636,"href":"/manual/33?pdf=636"}},{"number":2,"tools":[],"source":{"printed":"33-16 · 33 52 000","pdf":636,"href":"/manual/33?pdf=636"}},{"number":3,"tools":[],"source":{"printed":"33-16 · 33 52 000","pdf":636,"href":"/manual/33?pdf=636"}}]},"steps":[{"title":"Expose the mount and support the arm","body":"Move aside trunk trim. Support the semi-trailing arm before releasing the lower shock bolt. Protect nearby brake hoses and body trim.","check":"The trailing arm remains supported as the shock is unloaded."},{"title":"Change the shock or upper mount","body":"Remove the upper mount fasteners and withdraw the shock. Replace the gasket. If reusing the mount, inspect its rubber and tighten the original shaft nut to 15 Nm with the correct counterhold. Prime dampers only as their manufacturer specifies.","check":"The gasket sits flat and the mount has no torn rubber or looseness."},{"title":"Tighten at installed height","body":"Tighten the upper M8 fasteners to 22 Nm. Bring the arm to normal ride position and use the confirmed lower-bolt specification for its grade and source.","check":"The hardware is secure, the arm moves freely, and the trim is refitted."}]}'::jsonb),
('e30-handbrake-adjustment','b2f82aaafa71d7204a2c8bd5','{"slug":"e30-handbrake-adjustment","title":"Adjust the rear-disc parking brake","system":"brakes","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"30–60 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Rear-wheel-drive E30 with the separate shoes inside the rear rotor hats. Rear drum versions use their own adjustment.","reviewStatus":"draft","sourceChecked":true,"applicability":"Rear-wheel-drive E30 with the separate shoes inside the rear rotor hats. Rear drum versions use their own adjustment.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"34-3 · 34 10 014","pdfPages":[642]},"evidence":[{"label":"BMW · 34-3, parking brake adjustment","href":"/manual/34?pdf=642"},{"label":"1991 325i coupe · parking brake shoe diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/brakes_pedals/parking_brake_brake_shoes.html"}],"tools":["Slotted screwdriver that reaches through the wheel bolt hole, spanners matched to the cable nuts, and a wheel socket and torque wrench."],"cautions":["Chock the wheels and use a rated lift or stands. Keep the removed assembly supported separately.","This is the disc-brake layout with small shoes inside the rear rotor hats. Repair a seized cable or contaminated shoe before adjusting."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":[],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"34-3 · 34 10 014","pdf":642,"href":"/manual/34?pdf=642"}},{"number":2,"tools":[],"source":{"printed":"34-3 · 34 10 014","pdf":642,"href":"/manual/34?pdf=642"}},{"number":3,"tools":[],"source":{"printed":"34-3 · 34 10 014","pdf":642,"href":"/manual/34?pdf=642"}}]},"steps":[{"title":"Back off the cables","body":"Release the parking brake fully. Check that both cables move freely. Lift the lever boot and loosen the cable adjusting nuts so the shoes can settle.","check":"Both rear wheels turn with the brake released."},{"title":"Adjust each shoe set at the rotor","body":"Remove one wheel bolt per side. Rotate the access hole about 30° rearward of vertical. Use a flat screwdriver to expand the shoes until the rotor locks, then back off three or four adjuster teeth.","check":"Each rotor turns easily with the lever released."},{"title":"Balance the cables","body":"Raise the lever five clicks. Adjust both cable nuts until both wheels just turn with even resistance. Release the lever and check free rotation and warning switch operation. Refit the original wheel bolts and torque to 110 Nm.","check":"Both sides hold and release evenly."}]}'::jsonb),
('e30-parking-brake-shoes','c618492d0afea230d867cf0c','{"slug":"e30-parking-brake-shoes","title":"Replace the rear-disc parking brake shoes","system":"brakes","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"1–2 hr per axle","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"E30 325i with the original rear disc and internal parking-brake shoes.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 325i with the original rear disc and internal parking-brake shoes.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"34-17 · 34 41 200","pdfPages":[649,660,642]},"relatedGuides":["e30-rear-brake-pads-discs","e30-handbrake-adjustment"],"evidence":[{"label":"BMW · 34-17, parking brake shoe replacement","href":"/manual/34?pdf=660"},{"label":"BMW · 34-3, parking brake adjustment","href":"/manual/34?pdf=642"},{"label":"BMW · 34-9, rear disc removal","href":"/manual/34?pdf=649"},{"label":"1991 325i coupe · parking brake shoe diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/brakes_pedals/parking_brake_brake_shoes.html"}],"tools":["BMW 34 4 000 spring-retainer tool. Use the rear brake procedure for the 7 mm hex guide bolts, caliper hanger and rotor fasteners."],"cautions":["Chock the wheels and use a rated lift or stands. Keep the removed assembly supported separately.","Avoid inhaling brake dust. Keep friction surfaces clean and verify the brake works before road use."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Matched parking brake shoes for both rear rotors. Replace damaged retainers, springs or adjusters."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"34-17 · 34 41 200","pdf":649,"href":"/manual/34?pdf=649"}},{"number":2,"tools":[],"source":{"printed":"34-17 · 34 41 200","pdf":660,"href":"/manual/34?pdf=660"}},{"number":3,"tools":[],"source":{"printed":"34-17 · 34 41 200","pdf":642,"href":"/manual/34?pdf=642"}}]},"steps":[{"title":"Expose the shoe hardware","body":"Release the cables and remove both rear brake discs using the rear brake guide. Support the calipers independently of the hoses. Compare the drum surfaces and shoe layout before removing anything.","check":"The rotor hats are serviceable and both sets of hardware can be compared."},{"title":"Replace and orient the shoes","body":"Unhook the return springs. Use BMW 34 4 000 to turn and release the spring retainers. Refit the shoes, expansion lock, adjuster and springs in their illustrated positions.","check":"All retainers are locked and each shoe moves without binding."},{"title":"Refit and adjust","body":"Reinstall the rear discs and tighten their retaining screws to 16 Nm. Refit the calipers with the applicable torques in the rear brake guide. Set shoe clearance and balance the cables using 34 10 014.","check":"The parking brake holds evenly, releases fully, and the foot pedal is firm."}]}'::jsonb),
('e30-sunroof-alignment','fba9acd1b7e871dffebeb53e','{"slug":"e30-sunroof-alignment","title":"Align the steel sunroof panel","system":"body","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"45–90 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"E30 factory sliding and tilting steel sunroof with the guide and gate shown in BMW 54 12 004.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 factory sliding and tilting steel sunroof with the guide and gate shown in BMW 54 12 004.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"54-1 · 54 12 004","pdfPages":[1057]},"evidence":[{"label":"BMW · 54-1, panel height and adjustment","href":"/manual/54?pdf=1057"}],"tools":["Two 4 mm keys for the guide locks, BMW 00 2 102/103 for the adjusters, straightedge, 0.2 mm plastic gauge and low-range torque wrench."],"cautions":["Keep fingers clear of the opening. Stop if the guides are damaged or a seized cable prevents both sides from reaching the closed position together."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["New self-locking panel screws for the six fasteners removed or loosened for adjustment."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"54-1 · 54 12 004","pdf":1057,"href":"/manual/54?pdf=1057"}},{"number":2,"tools":[],"source":{"printed":"54-1 · 54 12 004","pdf":1057,"href":"/manual/54?pdf=1057"}},{"number":3,"tools":[],"source":{"printed":"54-1 · 54 12 004","pdf":1057,"href":"/manual/54?pdf=1057"}}]},"steps":[{"title":"Free the liner and close the panel","body":"Open the roof about 50 mm and release the front liner frame. Close the lid and slide the liner back. Lock the left and right guides at the closed position with 4 mm keys as shown.","check":"Both guides are at position zero and the liner is out of the way."},{"title":"Set height and gap","body":"Use BMW 00 2 102/103 to loosen the three adjusters per side. With a straightedge, set the front edge 1 mm below the roof and the rear edge 1 mm above. Compare the front and rear gaps with a plastic gauge.","check":"Panel height and spacing match the factory drawing and the seal is even."},{"title":"Secure and cycle","body":"Set new self-locking screws to 3.5 Nm. Remove both locking keys. Reclip the liner as BMW shows and check that the roof slides, tilts and closes without contacting paint or trim.","check":"The panel is seated and the closed position repeats."}]}'::jsonb),
('e30-heater-blower','f5041bce229c8fd314992be9','{"slug":"e30-heater-blower","title":"Replace the heater blower motor","system":"climate","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"45–90 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"E30 cowl-access blower shown in BMW 64 11 210. Match the motor code and housing before buying.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 cowl-access blower shown in BMW 64 11 210. Match the motor code and housing before buying.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"64-9 · 64 11 210","pdfPages":[1205]},"evidence":[{"label":"BMW · 64-9, blower motor removal and code","href":"/manual/64?pdf=1205"},{"label":"1991 325i coupe · heater core, valves and blower diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/heater_and_air_conditioning/heater_radiator_blower.html"}],"tools":["Fastener driver matched to the cowl access panel, trim tool and side cutters for the original loom tie."],"cautions":["Switch off the ignition and disconnect the battery ground before disconnecting the wiring.","Keep the wheels and motor as a balanced assembly. Protect the air flap and keep hands out of the fan when power is restored."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Balanced motor and fan-wheel assembly matched to the installed housing."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"64-9 · 64 11 210","pdf":1205,"href":"/manual/64?pdf=1205"}},{"number":2,"tools":[],"source":{"printed":"64-9 · 64 11 210","pdf":1205,"href":"/manual/64?pdf=1205"}},{"number":3,"tools":[],"source":{"printed":"64-9 · 64 11 210","pdf":1205,"href":"/manual/64?pdf=1205"}}]},"steps":[{"title":"Open the cowl access","body":"Lift the cowl seal. Release the loom fastener without cutting wires, then move the access cover aside. Release both heater-cover retaining straps.","check":"The blower is accessible and the loom is supported."},{"title":"Remove and match the assembly","body":"Photograph and unplug the two motor leads. Release the center clamp, then lift the motor and both fans clear of the air flap. Match the original housing and motor code.","check":"Both wheels are intact and the replacement drops into the same supports."},{"title":"Check spin and refit","body":"Clamp the motor in place and check that the wheels turn freely by hand. Restore the connectors, access covers, seal and loom tie. Reconnect the battery and check every fan speed.","check":"The blower runs without scraping or excessive vibration."}]}'::jsonb),
('e30-blower-resistor','698fb4f4790dd5fd4d2a7964','{"slug":"e30-blower-resistor","title":"Replace the heater blower resistor","system":"climate","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"30–60 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"E30 cowl-access resistor plate shown in BMW 64 11 220. Check its connector and fitted housing.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 cowl-access resistor plate shown in BMW 64 11 220. Check its connector and fitted housing.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"64-11 · 64 11 220","pdfPages":[1206]},"evidence":[{"label":"BMW · 64-11, blower resistor access","href":"/manual/64?pdf=1206"},{"label":"1991 325i coupe · heater core, valves and blower diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/heater_and_air_conditioning/heater_radiator_blower.html"}],"tools":["Driver for the actual cowl cover screws, trim tool and cutters for the original loom tie."],"cautions":["Switch off the ignition and disconnect the battery ground before disconnecting the wiring.","A resistor runs hot. Check for a stiff blower, restricted air path or melted connector before replacing the resistor alone."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Resistor plate matched to the installed blower housing and connector."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"64-11 · 64 11 220","pdf":1206,"href":"/manual/64?pdf=1206"}},{"number":2,"tools":[],"source":{"printed":"64-11 · 64 11 220","pdf":1206,"href":"/manual/64?pdf=1206"}},{"number":3,"tools":[],"source":{"printed":"64-11 · 64 11 220","pdf":1206,"href":"/manual/64?pdf=1206"}}]},"steps":[{"title":"Access the resistor plate","body":"Pull back the cowl seal, free the harness tie and move the access panel. Release the retaining straps and find the resistor plate in its illustrated air passage.","check":"The plate and connector can move without pulling on the loom."},{"title":"Inspect and replace","body":"Pull the plate out of its socket. Inspect for heat damage, debris and a binding blower wheel. Fit the matching plate fully in its cooling-air position.","check":"The connector is firm and the resistor is flush in the duct."},{"title":"Restore covers and test","body":"Secure the cowl cover and seal, reconnect the battery, then test every speed. Stop if the connector heats, smells burnt or the fan slows unexpectedly.","check":"Each fan setting works and air reaches the vents."}]}'::jsonb),
('e30-heater-valve','5bdb5a90eee5004f1aa0fb9e','{"slug":"e30-heater-valve","title":"Replace the heater water valve","system":"climate","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"1–2 hr plus cool-down","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Left-hand-drive E30 325i with the valve and pipe joints shown in BMW 64 11 271.","reviewStatus":"draft","sourceChecked":true,"applicability":"Left-hand-drive E30 325i with the valve and pipe joints shown in BMW 64 11 271.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"64-12 · 64 11 271","pdfPages":[1207,332]},"relatedGuides":["e30-coolant-bleeding"],"evidence":[{"label":"BMW · 64-12, heater valve and seal","href":"/manual/64?pdf=1207"},{"label":"1991 325i coupe · heater core, valves and blower diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/heater_and_air_conditioning/heater_radiator_blower.html"}],"tools":["Trim driver, clamp driver, short socket or driver matched to the valve joint and an 8 mm wrench for the original M20 bleeder."],"cautions":["Wait for the engine and coolant to cool completely before opening the system. Catch the coolant and keep it away from children and animals.","Switch off the ignition and disconnect the battery ground before disconnecting the wiring."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Heater water valve and new pipe seals for the installed heater box."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"64-12 · 64 11 271","pdf":1207,"href":"/manual/64?pdf=1207"}},{"number":2,"tools":[],"source":{"printed":"64-12 · 64 11 271","pdf":1207,"href":"/manual/64?pdf=1207"}},{"number":3,"tools":[],"source":{"printed":"64-12 · 64 11 271","pdf":332,"href":"/manual/17?pdf=332"}}]},"steps":[{"title":"Expose the valve and catch coolant","body":"Remove the left lower dash trim and tray as shown. Drain coolant, protect the carpet and trace the heater hoses and valve connector before disconnecting them.","check":"The valve is accessible and any runoff is captured."},{"title":"Unfasten and replace the valve","body":"Unplug the valve, release its clamp and unfasten the pipe joints without flexing the pipes. Renew the valve seal and seat each pipe squarely before securing it.","check":"The pipe joints line up and the wiring is clear of moving pedals."},{"title":"Bleed and check operation","body":"Reconnect the hoses and electrical plug. Refill and bleed the cooling system. Check for leaks behind the trim and confirm the controls can change cabin air temperature.","check":"The valve and pipe joints are dry before the trim goes back."}]}'::jsonb),
('e30-heater-core','2ef6baeafc5162d05bfc177f','{"slug":"e30-heater-core","title":"Replace the heater core","system":"climate","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"2–4 hr plus cool-down","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Left-hand-drive E30 325i with the heater case and footwell pipe routing in BMW 64 11 531.","reviewStatus":"draft","sourceChecked":true,"applicability":"Left-hand-drive E30 325i with the heater case and footwell pipe routing in BMW 64 11 531.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"64-14 · 64 11 531","pdfPages":[1210,332]},"relatedGuides":["e30-coolant-bleeding","e30-heater-valve"],"evidence":[{"label":"BMW · 64-14, heater core and pipe seals","href":"/manual/64?pdf=1210"},{"label":"1991 325i coupe · heater core, valves and blower diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/heater_and_air_conditioning/heater_radiator_blower.html"}],"tools":["Trim driver and short sockets or drivers matched to the pipe and core fasteners. Use an 8 mm wrench and low-range torque wrench for the M20 bleed screw."],"cautions":["Wait for the engine and coolant to cool completely before opening the system. Catch the coolant and keep it away from children and animals.","Switch off the ignition and disconnect the battery ground before disconnecting the wiring.","Cover the carpet and electrical connectors before opening any heater line."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Heater core and new pipe sealing rings for the installed heater box."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"64-14 · 64 11 531","pdf":1210,"href":"/manual/64?pdf=1210"}},{"number":2,"tools":[],"source":{"printed":"64-14 · 64 11 531","pdf":1210,"href":"/manual/64?pdf=1210"}},{"number":3,"tools":[],"source":{"printed":"64-14 · 64 11 531","pdf":332,"href":"/manual/17?pdf=332"}}]},"steps":[{"title":"Clear the driver-side access","body":"Remove the tray and lower dash panel. Drain and collect coolant. Free the heater duct connector and molded access piece in the order shown.","check":"The end of the core and both pipe connections are visible."},{"title":"Withdraw the core","body":"Support the coolant pipes while undoing their unions. Remove the core retaining bolts and slide the core straight out. Compare the flanges, orientation and seal seats against the replacement.","check":"The pipes and housing are undamaged and the seals match."},{"title":"Refill and leak-check before closing","body":"Slide the new core into the case and seat the new seals without forcing the pipes sideways. Refill and bleed the M20 system. Inspect the dry footwell and test the heater before installing the ducts and trim.","check":"Cabin heat is stable and the pipe joints and carpet remain dry."}]}'::jsonb),
('e30-mirror-switch','a44aac480ee9b346a65c0464','{"slug":"e30-mirror-switch","title":"Replace the power-mirror switch","system":"electrical","engines":["M20"],"level":"Beginner","kind":"replacement","duration":"15–30 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"E30 with the door-mounted selector and adjustment switch shown in BMW 61 31 255.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 with the door-mounted selector and adjustment switch shown in BMW 61 31 255.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"61-7 · 61 31 255","pdfPages":[1146]},"evidence":[{"label":"BMW · 61-7, power mirror switch replacement","href":"/manual/61?pdf=1146"},{"label":"1991 325i coupe · outside mirror and switch diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/vehicle_trim/outside_mirror.html"}],"tools":["BMW 61 1 300 switch extractor or a non-marring tool that supports the switch edge."],"cautions":["Switch off the ignition and disconnect the battery ground before disconnecting the wiring.","Protect the door trim and hold the connector while unplugging the switch."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Mirror switch with the same connector and adjustment functions."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"61-7 · 61 31 255","pdf":1146,"href":"/manual/61?pdf=1146"}},{"number":2,"tools":[],"source":{"printed":"61-7 · 61 31 255","pdf":1146,"href":"/manual/61?pdf=1146"}},{"number":3,"tools":[],"source":{"printed":"61-7 · 61 31 255","pdf":1146,"href":"/manual/61?pdf=1146"}}]},"steps":[{"title":"Remove the control knob","body":"Protect the surrounding door trim and lift the adjustment knob as illustrated.","check":"The knob and switch bezel are intact."},{"title":"Lift out the switch","body":"Use BMW 61 1 300 or a matching non-marring trim tool. Support the plug and disconnect it by the housing. Compare the connector layout before attaching the replacement.","check":"The connector is fully seated and the harness remains inside the door opening."},{"title":"Refit and test both sides","body":"Snap the switch into the trim, refit the knob and restore the battery. Test the selector and movement of both mirrors.","check":"Each mirror moves in all four directions when selected."}]}'::jsonb),
('e30-sealed-beam-headlight','cd4db9ef45f4de122eb854b6','{"slug":"e30-sealed-beam-headlight","title":"Replace a sealed-beam headlight insert","system":"electrical","engines":["M20"],"level":"Beginner","kind":"replacement","duration":"25–45 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"U.S. E30 325i with four sealed-beam lamps, the late arrangement cataloged from 06/1989.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. E30 325i with four sealed-beam lamps, the late arrangement cataloged from 06/1989.","source":{"id":"e30-owner-handbook","title":"BMW 325i / 325is owner’s handbook","section":"BMW 325i handbook · p. 60","pdfPages":[]},"evidence":[{"label":"BMW 325i handbook · sealed-beam headlight installation, p. 60","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=61"},{"label":"Philips · U.S. 1990–91 325i lighting applications","href":"https://www.philips.com/c-dam/b2c/en_US/generic/support-home/support-page-product-flyers/automotive-lighting-tab-product-flyers/philips-classic-car-lighting-catalog-1946-2002.pdf"},{"label":"1991 325i coupe · late sealed-beam lamp diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/lighting/single_components_for_headlight.html"}],"tools":["Driver that seats in the grille and three clamping-ring screws. Proper beam-setting equipment for the aim check."],"cautions":["Switch off the ignition and disconnect the battery ground before disconnecting the wiring.","Stop if the connector shows heat damage or the lamp seat is broken. Have aim checked after refitting."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"df0694c579fdbd0e4e671675f510db3fc09fd136b70e4c034fea28c607a387f3","requiredParts":["Matching sealed-beam insert identified as outer low beam or inner high beam."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"BMW 325i handbook · sealed-beam headlight installation, p. 60","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=61"}},{"number":2,"tools":[],"source":{"printed":"BMW 325i handbook · sealed-beam headlight installation, p. 60","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=61"}},{"number":3,"tools":[],"source":{"printed":"BMW 325i handbook · sealed-beam headlight installation, p. 60","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=61"}}]},"steps":[{"title":"Identify the lamp","body":"Use the two outer inserts for low beam and the two inner inserts for high beam. Match the lens marking and connector on the failed unit.","check":"The replacement is the correct beam position and connector type."},{"title":"Release the clamping ring","body":"Remove the grille section and support the insert while loosening its three ring screws. Unplug the insert without disturbing the beam adjustment screws.","check":"The reflector carrier and adjusters have stayed in place."},{"title":"Seat and verify the lamp","body":"Engage the insert’s locating features and secure the ring and grille. Restore power and check both beam settings. Have the aiming pattern checked with the correct equipment.","check":"The lamp is seated firmly and lights in the correct switch position."}]}'::jsonb),
('e30-fog-light-bulb','c1d7a1494c88b82a41998c5c','{"slug":"e30-fog-light-bulb","title":"Replace a late front fog light bulb","system":"electrical","engines":["M20"],"level":"Beginner","kind":"replacement","duration":"20–40 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Late E30 with the 09/1987-on front housing that accepts the H3 bulb.","reviewStatus":"draft","sourceChecked":true,"applicability":"Late E30 with the 09/1987-on front housing that accepts the H3 bulb.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"63 99 201 · front fog lamp","pdfPages":[1191]},"evidence":[{"label":"BMW · 63 99 201, front fog bulb replacement","href":"/manual/63?pdf=1191"},{"label":"1991 325i coupe · late fog lamp diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/lighting/fog_lights.html"}],"tools":["Driver that fits the lamp frame retaining screws and a clean cloth for handling the bulb."],"cautions":["Switch off the ignition and disconnect the battery ground before disconnecting the wiring.","Let the lamp cool. Handle a halogen bulb by its base and protect the glass from scratches and fingerprints."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["H3 12 V 55 W bulb for the late catalog housing. Replace damaged seals as needed."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"63 99 201 · front fog lamp","pdf":1191,"href":"/manual/63?pdf=1191"}},{"number":2,"tools":[],"source":{"printed":"63 99 201 · front fog lamp","pdf":1191,"href":"/manual/63?pdf=1191"}},{"number":3,"tools":[],"source":{"printed":"63 99 201 · front fog lamp","pdf":1191,"href":"/manual/63?pdf=1191"}}]},"steps":[{"title":"Free the lamp housing","body":"Remove the retaining screws and withdraw the lamp from the holding frame shown in the manual. Support the housing by hand.","check":"The lamp is supported and the wiring has slack."},{"title":"Replace the bulb","body":"Disconnect the plug, open the rear cover and release the spring clip. Seat the H3 replacement with the same tab orientation before locking the clip.","check":"The bulb is flat in its seat and the lead is attached."},{"title":"Seal the lamp and test","body":"Check the seal, close the cover and reinstall the housing. Restore power and check the fog lights and their mounting angle.","check":"Both lamps work and the repaired housing is secure."}]}'::jsonb),
('e30-wiper-blades','3c0bce1cfaa10c4c02cab202','{"slug":"e30-wiper-blades","title":"Replace the front wiper blades","system":"body","engines":["M20"],"level":"Beginner","kind":"replacement","duration":"10–20 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"E30 325i with original spring-latch front wiper arms. Match any replacement arm’s latch.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 325i with original spring-latch front wiper arms. Match any replacement arm’s latch.","source":{"id":"e30-owner-handbook","title":"BMW 325i / 325is owner’s handbook","section":"BMW 325i handbook · p. 59","pdfPages":[]},"evidence":[{"label":"BMW 325i handbook · front wiper blade removal, p. 59","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=60"},{"label":"1991 325i coupe · wiper arms and blades diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/vehicle_electrical_system/wiper_arm_wiper_blade.html"}],"tools":["Folded towel to protect the windshield and a ruler to verify both blade lengths."],"cautions":["Support the bare arm and protect the glass. Free frozen blades before operating the wipers."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"df0694c579fdbd0e4e671675f510db3fc09fd136b70e4c034fea28c607a387f3","requiredParts":["Two blades matched to the fitted arm latch. The standard pair is nominally 500 mm each."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"BMW 325i handbook · front wiper blade removal, p. 59","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=60"}},{"number":2,"tools":[],"source":{"printed":"BMW 325i handbook · front wiper blade removal, p. 59","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=60"}},{"number":3,"tools":[],"source":{"printed":"BMW 325i handbook · front wiper blade removal, p. 59","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=60"}}]},"steps":[{"title":"Match the replacement and protect the glass","body":"Check the two blade lengths and latch styles. Switch the wipers off at rest, then protect the windshield with a folded towel.","check":"Both replacements match their arm and the glass is covered."},{"title":"Release and fit one blade at a time","body":"Lift the arm away from the glass. Press the retaining spring, slide the old blade off and engage the replacement latch before lowering the arm.","check":"The new blade stays on when lightly pulled against the latch."},{"title":"Check sweep and park","body":"Wet the glass and run the wipers. Check the full sweep and parked position for interference with the trim and between the blades.","check":"Both blades park correctly and stay attached."}]}'::jsonb),
('e30-power-steering-bleed','d6cb429d9a2167fc98733195','{"slug":"e30-power-steering-bleed","title":"Fill and bleed the power steering","system":"suspension","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"20–40 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"E30 with the hydraulic rack and dipstick-equipped reservoir in BMW 32 13 006.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 with the hydraulic rack and dipstick-equipped reservoir in BMW 32 13 006.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"32-6b · 32 13 006","pdfPages":[572]},"evidence":[{"label":"BMW · 32-6b, power steering filling and bleeding","href":"/manual/32?pdf=572"}],"tools":["Clean funnel, absorbent cloth and the reservoir dipstick."],"cautions":["Confirm the fluid on the reservoir label. Keep clear of belts, preserve the pump supply and avoid holding the steering at full lock."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Hydraulic fluid specified for the fitted reservoir and system."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"32-6b · 32 13 006","pdf":572,"href":"/manual/32?pdf=572"}},{"number":2,"tools":[],"source":{"printed":"32-6b · 32 13 006","pdf":572,"href":"/manual/32?pdf=572"}},{"number":3,"tools":[],"source":{"printed":"32-6b · 32 13 006","pdf":572,"href":"/manual/32?pdf=572"}}]},"steps":[{"title":"Check the system before filling","body":"Identify the fluid and inspect the suction hose, return hose and rack connections for leaks. With the engine stopped, fill to the MAX mark on the dipstick.","check":"The fluid is correct and the pump feed stays covered."},{"title":"Cycle the steering","body":"Start the engine in a ventilated area. Sweep the steering toward each side twice without holding it at the stop. Shut off the engine and inspect the reservoir.","check":"Foaming and noise settle and the reservoir remains supplied."},{"title":"Recheck level and leaks","body":"With the engine off, correct the level to the reference mark. Check the disturbed joints and confirm normal assist without noise. If the fluid continues to foam, inspect the suction side for air entry.","check":"Fluid level stays stable and steering assist is even."}]}'::jsonb)
